    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Steam Vents",
      "level": 4,
      "rarity": "uncommon",
      "size": "medium",
      "traits": [
        "mechanical",
        "trap",
        "steam"
      ],
      "description": "Large pressurized pipes connected to a trip wire are rigged to release a blast of steam on trespassers.",
      "armorClass": 20,
      "hitPoints": 48,
      "hardness": 12,
      "stealth": {
        "modifier": 12,
        "details": "(trained)"
      },
      "disable": "check (thievery, dc:22, name:Disconnect the trip wire, traits:mechanical,trap,hazard) to disconnect the trip wire or a check (crafting, dc:24, name:Reduce the pressure, traits:mechanical,trap,hazard) to carefully reduce the pressure and prevent the blast",
      "isComplex": false,
      "routine": "",
      "reset": "",
      "saves": {
        "fortitude": 12,
        "reflex": 12,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "SvqJNCRH2eI1jZk1",
          "name": "Steam Blast",
          "kind": "reaction",
          "description": "Trigger The trip wire is pulled or severed, typically because a creature walked through the square with the trip wire\nEffect Steam erupts from the pipes, dealing 3d6 bludgeoning damage] (check (reflex, dc:24, basic, name:Avoid the erupting steam, traits:mechanical,trap,hazard)) to all creatures within 15 feet. Creatures that critically fail their save are knocked Prone.",
          "traits": []
        }
      ]
    },
