        {
          "id": "Ng7mcTvdebJG5k0Q",
          "name": "+1 Status to All Saves vs. Magic",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "dZXxGiQZC9DOZzVL",
          "name": "Correcting Veil",
          "kind": "passive",
          "description": "100 feet. The instillo's telepathic presence constantly monitors perspectives and molds thought toward an infernal clarity. Creatures within the aura gain the Dubious Knowledge skill feat but are unaware of this effect. The instillo is instantly aware when any creature within the aura fails a Recall Knowledge check and influences the erroneous information that the creature gains.",
          "traits": [
            "aura",
            "linguistic",
            "mental",
            "subtle"
          ]
        },
        {
          "id": "fcqzeGyBkWPV91oF",
          "name": "Nod of the Tongue",
          "kind": "passive",
          "description": "Creatures who can understand Diabolic take a –2 status penalty to their Will saves against the instillo's effects with the auditory or mental trait.",
          "traits": []
        },
        {
          "id": "yhPtNDLylmO8tvYN",
          "name": "Quiet Confidence",
          "kind": "action",
          "description": "The instillo can hide the source of their magic. If the next action the instillo uses is to Cast a Spell, that spell gains the subtle trait. The trait hides only the spell's spellcasting actions and manifestations, not its effects.",
          "traits": [
            "concentrate",
            "spellshape"
          ]
        },
        {
          "id": "Ys3UY4v5qkIzwiPW",
          "name": "Sneak Attack",
          "kind": "passive",
          "description": "The instillo's Strikes deal an additional 2d6 precision damage to Off-Guard creatures.",
          "traits": []
        },
        {
          "id": "4NxpXIphSKvv9Jfq",
          "name": "Superlative Rhetoric",
          "kind": "action",
          "description": "Frequency once per round\nRequirements The instillo's most recent action was to cast a spell with the auditory trait\nEffect The instillo immediately casts Daze at a creature that can hear them.",
          "traits": [
            "arcane"
          ]
        }
