        {
          "id": "QDMXH5o8ftWutjTp",
          "name": "Hidden Familiar",
          "kind": "passive",
          "description": "Varlario has Hidden their bat familiar through the Pet Cache spell. They keep the bat contained except when they use shred spirit.",
          "traits": []
        },
        {
          "id": "xNrqFLKceXzkzUGF",
          "name": "Shred Spirit",
          "kind": "action",
          "description": "Frequency once per minute\nEffect Varlario sends forth their bat familiar as a phantasmal conduit to rip at the soul of a creature within 30 feet. The targeted creature must succeed at a check (will, dc:26, basic) save or take 9d6 spirit damage. Varlario then recovers Hit Points equal to half the damage dealt.",
          "traits": [
            "concentrate",
            "spirit"
          ]
        }
