    "data": {
      "schemaVersion": 1,
      "name": "Elite Mutant Cryptid Snapdrake",
      "level": 10,
      "rarity": "rare",
      "size": "large",
      "traits": [
        "elemental",
        "plant",
        "wood"
      ],
      "description": "Skilled kizidhar mages and gardeners handcraft these lovely creatures as much for their shuyookhs' aesthetic pleasure as for their protection. Creating a snapdrake requires first painstakingly constructing a frame of living wood in the shape of a drake before weaving thousands of colorful snapdragon flowers into intricate patterns to form its body and scales. Once complete, snapdrakes often serve kizidhars as a combination of guards, pets, and decorations for as long as they are well fed.",
      "armorClass": 26,
      "hitPoints": 144,
      "speedFeet": 20,
      "perception": {
        "modifier": 19,
        "senses": []
      },
      "saves": {
        "fortitude": 16,
        "reflex": 11,
        "will": 19
      },
      "abilities": {
        "str": 4,
        "dex": 6,
        "con": 3,
        "int": -2,
        "wis": 3,
        "cha": 4
      },
      "skills": {
        "acrobatics": 18,
        "performance": 19
      },
      "languages": [
        "arboreal",
        "common",
        "muan"
      ],
      "defenses": {
        "immunities": [
          "bleed",
          "paralyzed",
          "poison",
          "sleep"
        ],
        "resistances": [],
        "weaknesses": [
          "axe-vulnerability 10",
          "fire 10"
        ]
      },
      "attacks": [
        {
          "id": "03YaLZZBbaQNXIgl",
          "name": "Fangs",
          "bonus": 17,
          "damage": "2d12+7 piercing",
          "traits": []
        },
        {
          "id": "u2nE2RBWdzAHKWHI",
          "name": "Tail Scythe",
          "bonus": 19,
          "damage": "2d10+9 slashing",
          "traits": [
            "deadly-d10",
            "finesse",
            "reach-10"
          ]
        }
      ],
      "actions": [
        {
          "id": "oWKqHA1A1VMXlVm8",
          "name": "Alluring Scent",
          "kind": "passive",
          "description": "30 feet. A creature that enters the emanation must attempt a check (will, dc:28) save. On a failure, the target is Fascinated by the snapdrake and must use at least 1 action on its next turn to Stride closer to the snapdrake. On a success, the target is immune to the snapdrake's alluring scent for 1 hour.",
          "traits": [
            "aura",
            "olfactory",
            "plant",
            "primal"
          ]
        },
        {
          "id": "KufKnciuq8utQN8u",
          "name": "Reactive Strike (Tail Scythe Only)",
          "kind": "reaction",
          "description": "",
          "traits": []
        },
        {
          "id": "ca38dLMDKd24UQE3",
          "name": "Explosive End",
          "kind": "passive",
          "description": "The mutant snapdrake's death reveals one last surprise as it explodes into splinters. When it dies, it explodes, dealing 5d6 piercing damage to each creature in a 10-foot emanation, with a check (reflex, dc:30, basic, options:area-effect) save.",
          "traits": []
        },
        {
          "id": "7RD9b0b0ARSHZeZJ",
          "name": "Greater Forest Passage",
          "kind": "passive",
          "description": "The snapdrake ignores difficult terrain and greater difficult terrain from plants and fungi.",
          "traits": []
        },
        {
          "id": "LE6KUpPto7uLf1bD",
          "name": "Marrowlance",
          "kind": "passive",
          "description": "The mutant cryptid can make wicked spears of bone erupt from its body. The creature can make marrowlance ranged unarmed attacks. Use the highest attack modifier from the creature's highest ranged Strike, as well as the damage from that Strike. If it has no ranged attacks, use moderate accuracy and low damage for the creature's level. Marrowlance unarmed attacks have a range of 60 feet and the versatile S trait.",
          "traits": []
        },
        {
          "id": "JfmizJJ6WCZlKigo",
          "name": "Shifting Iridescence",
          "kind": "passive",
          "description": "Whenever the mutant snapdrake takes energy damage to which it isn't resistant or immune, after taking the damage normally, it gains resistance 10 to that damage type. If it had a resistance to a different damage type from shifting iridescence, it replaces the old resistance with the new resistance.",
          "traits": [
            "magical"
          ]
        },
        {
          "id": "HAmEsoCS7jucJCnL",
          "name": "Snapdrake Pollen",
          "kind": "passive",
          "description": "Saving Throw check (fortitude, dc:30)\nMaximum Duration 8 rounds\nStage 1 1d6 poison damage plus Dazzled (1 round)\nStage 2 1d6 poison damage plus dazzled and Sickened 1 (2 rounds)\nStage 3 2d6 poison damage plus Confused and sickened 1 (2 rounds)",
          "traits": [
            "plant",
            "poison"
          ]
        },
        {
          "id": "dupxU1QENo5dwXMD",
          "name": "Speed Surge",
          "kind": "action",
          "description": "Frequency 3 times per day\nEffect The snapdrake moves up to twice its Speed.",
          "traits": [
            "move"
          ]
        },
        {
          "id": "YsP0BTGgFbqhPJlq",
          "name": "Spray Pollen",
          "kind": "action",
          "description": "The snapdrake breathes a blast of pollen in a 40-foot cone. Creatures caught in the blast must succeed at a check (reflex, dc:28, basic) save or be exposed to snapdrake pollen. The snapdrake can't use Spray Pollen again for 1d6.",
          "traits": [
            "arcane",
            "plant",
            "poison"
          ]
        },
        {
          "id": "yI5Ldk4hGFFE02Xs",
          "name": "Unusual Bane",
          "kind": "passive",
          "description": "This mutant snapdrake is traumatized by the former Conference Z staff who teamed up to hold it down while experimenting on it. The first time each round the mutant snapdrake comes within 15 feet of any character who took the Aid action, or is attacked while being flanked by two characters, it takes 10 mental damage and must attempt a check (will, dc:30) save. On a failure, it is Stunned 1 (Stunned 3 on a critical failure).",
          "traits": []
        },
        {
          "id": "33PlFFmeIlVuU3MF",
          "name": "Grab",
          "kind": "action",
          "description": "",
          "traits": []
        }
      ],
      "spellcasting": []
    },
