    "data": {
      "schemaVersion": 1,
      "name": "Gargarthezul",
      "level": 1,
      "rarity": "uncommon",
      "size": "medium",
      "traits": [
        "demon",
        "fiend",
        "unholy"
      ],
      "description": "",
      "armorClass": 16,
      "hitPoints": 21,
      "speedFeet": 25,
      "perception": {
        "modifier": 7,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 4,
        "reflex": 10,
        "will": 7
      },
      "abilities": {
        "str": 4,
        "dex": 3,
        "con": 1,
        "int": 0,
        "wis": 2,
        "cha": 3
      },
      "skills": {
        "acrobatics": 6,
        "athletics": 7,
        "deception": 6,
        "intimidation": 7,
        "stealth": 6
      },
      "languages": [
        "chthonian",
        "common"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": [
          "cold-iron 3",
          "holy 3"
        ]
      },
      "attacks": [
        {
          "id": "LSYnFI5K1H9lKaBI",
          "name": "Tentacle",
          "bonus": 7,
          "damage": "1d6+2 bludgeoning",
          "traits": [
            "magical",
            "unarmed",
            "unholy"
          ]
        }
      ],
      "actions": [
        {
          "id": "TFGAhdThUZSbfWk5",
          "name": "Telepathy (100 feet)",
          "kind": "passive",
          "description": "",
          "traits": [
            "aura",
            "magical",
            "mental"
          ]
        },
        {
          "id": "X6hOrjB6TIyhyMQ5",
          "name": "Bravado Aversion",
          "kind": "passive",
          "description": "A gargarthezul can't stand to be shown up. The first time each round a creature successfully Demoralizes, Shoves, or Trips a gargarthezul, it takes 1d6 mental damage.",
          "traits": []
        },
        {
          "id": "yRpNZFLbeUdqHQ8H",
          "name": "Bully",
          "kind": "action",
          "description": "The gargarthezul Shoves a creature, and Strides after it into the nearest adjacent square if successful. It then makes a tentacle Strike against the creature, using the same multiple attack penalty.",
          "traits": []
        },
        {
          "id": "8eumTeww6536avGC",
          "name": "Halyard Swing",
          "kind": "action",
          "description": "Requirements The gargarthezul is on the deck of a ship.\nEffect The gargarthezul swings from a nearby rope, moving up to twice its Speed and ignoring any terrain or lack of surface beneath it. It can make a tentacle Strike at any point during this movement.",
          "traits": []
        },
        {
          "id": "QlktgKrcecMqG2Sa",
          "name": "Mark of Avarice",
          "kind": "action",
          "description": "Requirements The gargarthezul's last action was a successful tentacle Strike.\nEffect The gargarthezul places a brand on the creature it hit that fills the creature's mind with overwhelming urges towards piracy. The creature doesn't treat anyone as their ally and can't Delay or Ready. They must use all of their actions to attempt to Disarm, or Demoralize, targeting a creature randomly determined by the GM (they may use actions to facilitate their attempts, such as to move to the target or to drop an item so they have a free hand). The duration is based on a check (will, dc:17) save. If the creature successfully Disarms or Demoralizes their target, they can attempt a check (flat, dc:11) check to recover from Mark of Avarice. The gargarthezul may only have one mark of avarice in effect at any given time. An additional mark placed causes the previous one to fade.\nCritical Success The creature becomes temporarily immune for 1 minute.\nSuccess The creature is unaffected.\nFailure The mark lasts for 1 round.\nCritical Failure The mark lasts for 1 minute.",
          "traits": []
        },
        {
          "id": "jKfNuCn6j4e1lsfR",
          "name": "Vicious Bluster",
          "kind": "passive",
          "description": "When a gargarthezul successfully Demoralizes a foe, it gains 1d6 temporary Hit Points (2d6 on a critical success) that last for 1 minute.\nEffect: Vicious Bluster\nEffect: Vicious Bluster (Critical Success)",
          "traits": []
        }
      ],
      "spellcasting": []
    },
