    "translatableHash": "sha256:4d91da4ef3d494bdb16ab085eddd1ab286ec8fe4dae33578907b21cd2b912c64",
    "data": {
      "schemaVersion": 1,
      "name": "Demonbred Bottlenose Dolphin",
      "level": 1,
      "rarity": "uncommon",
      "size": "medium",
      "traits": [
        "animal",
        "unholy"
      ],
      "description": "The bottlenose dolphin is the most common and widespread species of dolphin. They are social predators who hunt shallow seas and rivers in large family groups called pods. Sailors are fond of bottlenose dolphins and frequently tell of how they've saved drowning mariners or protected crew from sharks with blows from their powerful snouts.\nDolphins encompass a wide range of aquatic mammals, all of which are social, intelligent, and widespread throughout the world's oceans.",
      "armorClass": 15,
      "hitPoints": 21,
      "speedFeet": 0,
      "perception": {
        "modifier": 8,
        "senses": [
          "echolocation-120",
          "low-light-vision"
        ]
      },
      "saves": {
        "fortitude": 7,
        "reflex": 8,
        "will": 6
      },
      "abilities": {
        "str": 2,
        "dex": 3,
        "con": 2,
        "int": -4,
        "wis": 3,
        "cha": 0
      },
      "skills": {
        "athletics": 7
      },
      "languages": [],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "cpSC9RcShIFK28EU",
          "name": "Snout",
          "bonus": 7,
          "damage": "1d6+3 bludgeoning",
          "traits": []
        },
        {
          "id": "5lPaA6GKal2YHAjj",
          "name": "Jaws",
          "bonus": 7,
          "damage": "1d6+3 piercing",
          "traits": [
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "TBp1tYUPtYoOEonO",
          "name": "Aquatic Echolocation 120 feet",
          "kind": "passive",
          "description": "A bottlenose dolphin can use its hearing as a precise sense at the listed range, but only underwater.",
          "traits": []
        },
        {
          "id": "khgGPSxgTQcgev3o",
          "name": "Deep Breath",
          "kind": "passive",
          "description": "A bottlenose dolphin can hold its breath for 2 hours.",
          "traits": []
        },
        {
          "id": "jN9qLXiQfaOBlFfC",
          "name": "Ramming Speed",
          "kind": "action",
          "description": "The bottlenose dolphin Swims twice and then makes a snout Strike. As long as it moved at least 20 feet, it gains a +1 circumstance bonus to its attack roll.\nA Large or smaller creature hit by this attack must succeed at a check (fortitude, dc:17) save or be Slowed 1 for 1 round.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
