    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Hostile Architecture (1-2)",
      "level": 2,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "magical",
        "trap",
        "unholy"
      ],
      "description": "The sigils on the door's frame glow with an amber light, which collects in a facet over the center of the door.",
      "armorClass": 18,
      "hitPoints": 30,
      "hardness": 7,
      "stealth": {
        "modifier": 8,
        "details": ""
      },
      "disable": "check (religion, dc:14) (trained) to strategically destroy the runes, check (thievery, dc:15) to disrupt the beam from collecting the facet, or Dispel Magic (1st rank, counteract DC 15) to dispel the rune",
      "isComplex": true,
      "routine": "a The hostile architecture fires its aversion beam on a creature that is sanctified holy. If there are no sanctified holy creatures, it instead fires its beam on the nearest non-demon creature.",
      "reset": "The hostile architecture resets after being exposed to the light of a blue moon.",
      "saves": {
        "fortitude": 11,
        "reflex": 5,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "0qNtBouiJtZ4CUMh",
          "name": "Aversion Beam",
          "kind": "reaction",
          "description": "Trigger A non-demon creature comes within 15 feet of the hostile architecture\nEffect The hostile architecture shines the aversion beam on the triggering creature, and then rolls initiative. The triggering creature must attempt a check (will, dc:18) save.\nCritical Success The target is immune to the trap for 1 minute.\nSuccess The target is unaffected.\nFailure The target is Frightened 1.\nCritical Failure The target is Frightened 3 and Fleeing.",
          "traits": [
            "attack",
            "fear",
            "magical",
            "mental"
          ]
        }
      ]
    },
