    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Hostile Architecture (3-4)",
      "level": 4,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "magical",
        "trap",
        "unholy"
      ],
      "description": "The sigils on the door's frame glow with an amber light, which collects in a facet over the center of the door.",
      "armorClass": 10,
      "hitPoints": 46,
      "hardness": 13,
      "stealth": {
        "modifier": 12,
        "details": ""
      },
      "disable": "check (religion, dc:17) (trained) to strategically destroy the runes, check (thievery, dc:18) to disrupt the beam from collecting the facet, or Dispel Magic (2nd rank, counteract DC 18) to dispel the rune",
      "isComplex": true,
      "routine": "a The hostile architecture fires its aversion beam on a creature that is sanctified holy. If there are no sanctified holy creatures, it instead fires its beam on the nearest non-demon creature.",
      "reset": "The Hostile Architecture resets after being exposed to the light of a blue moon.",
      "saves": {
        "fortitude": 14,
        "reflex": 8,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "0qNtBouiJtZ4CUMh",
          "name": "Aversion Beam",
          "kind": "reaction",
          "description": "Trigger A non-demon creature comes within 15 feet of the hostile architecture\nEffect The hostile architecture shines the aversion beam on the triggering creature, and then rolls initiative. The triggering creature must attempt a check (will, dc:21) save.\nCritical Success The target is immune to the trap for 1 minute.\nSuccess The target is unaffected.\nFailure The target is Frightened 1.\nCritical Failure The target is Frightened 3 and Fleeing.",
          "traits": [
            "attack",
            "fear",
            "magical",
            "mental"
          ]
        }
      ]
    },
