    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Sailor's Warning (5-6)",
      "level": 5,
      "rarity": "unique",
      "size": "medium",
      "traits": [
        "magical",
        "trap"
      ],
      "description": "An illusory cyclops in oracular robes cries out a warning, but then dissolves into a violent phantasmal cyclops, which calls out for the Blind Formless Chaos That Lies Behind the Stars to accept his sacrifice. It then plunges an obsidian athame into a creature's chest, summoning a foul entity.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 13,
        "details": "(trained)"
      },
      "disable": "check (arcana, dc:21) (trained) to repair Chamenaiti's magic, check (religion, dc:23) or check (occultism, dc:23) (trained) to offset the prayer, or Dispel Magic (3rd rank; counteract DC 21) to counteract the warning",
      "isComplex": true,
      "routine": "a Rubbery crimson tentacles appear from a rip in the air and grasp at all creatures in the area, dealing 1d6+3 bludgeoning damage] damage (check (fortitude, dc:22, basic) save).",
      "reset": "",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "93fXOGYchR42JY5W",
          "name": "Blood Sacrifice",
          "kind": "reaction",
          "description": "Trigger Sailing Mission 5 begins;\nEffect The trap makes an athame Strike against a random creature, and then rolls initiative.",
          "traits": []
        }
      ]
    },
