      "actions": [
        {
          "id": "jbjsVEFvVsslwVHa",
          "name": "Tail Lash",
          "kind": "reaction",
          "description": "Trigger A creature within reach of the ocean drake's tail uses an action to Strike or attempt a skill check.\nEffect The ocean drake attempts to Strike the triggering creature with its tail. If it hits, the creature takes a -2 circumstance penalty to the triggering roll.\nEffect: Tail Lash",
          "traits": []
        },
        {
          "id": "xheziaVMnj1iAjP5",
          "name": "Chthonic Mucus",
          "kind": "action",
          "description": "The ocean drake spits a ball of chthonic mucus up to a range of 50 feet that explodes in a 10-foot burst. Creatures within the burst take 4d6 spirit damage (check (reflex, dc:19, basic, options:area-effect) save). Those that fail this save also take 1d6 persistent spirit damage and take a –5-foot status penalty to their Speed. This Speed reduction ends with the persistent spirit damage.\nThe ocean drake can't use Chthonic Mucus again for 1d6.\nEffect: Chthonic Mucus",
          "traits": [
            "primal",
            "unholy"
          ]
        },
        {
          "id": "GsSxwd5EPNBqxdWC",
          "name": "Draconic Frenzy",
          "kind": "action",
          "description": "The river drake makes one Fangs Strike and two Tail Strikes in any order.",
          "traits": []
        },
        {
          "id": "qugqAWTLubz9fcj2",
          "name": "Speed Surge",
          "kind": "action",
          "description": "Frequency three times per day;\nEffect The river drake Strides or Flies twice.",
          "traits": [
            "move"
          ]
        }
      ],
