      "name": "Accursed Cargo (5-6)",
      "level": 6,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "magical",
        "trap",
        "unholy"
      ],
      "description": "A wooden crate bearing a chthonic sigil glows with a power contained within it.",
      "armorClass": 21,
      "hitPoints": 54,
      "hardness": 7,
      "stealth": {
        "modifier": 11,
        "details": "or Detect Magic"
      },
      "disable": "check (thievery, dc:25) (trained) to open the crate with gradual release of its magical energy, or Dispel Magic (2nd rank; counteract DC 21) to dispel the rune",
