    "translatableHash": "sha256:4909a29e4f0fdaa0fa49cf7c17b0879c69b00d7ca70bf59bf52338530edbd332",
    "data": {
      "schemaVersion": 1,
      "name": "Pathfinder Defender",
      "level": 7,
      "rarity": "uncommon",
      "size": "medium",
      "traits": [
        "incorporeal",
        "undead"
      ],
      "description": "Shadows that spend long amounts of time on the Netherworld and absorb its magic become greater shadows.\nThe mysterious undead known as shadows lurk in dark places and feed on those who stray too far from the light.",
      "armorClass": 24,
      "hitPoints": 75,
      "speedFeet": 0,
      "perception": {
        "modifier": 14,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 11,
        "reflex": 18,
        "will": 15
      },
      "abilities": {
        "str": -5,
        "dex": 5,
        "con": 0,
        "int": 0,
        "wis": 2,
        "cha": 4
      },
      "skills": {
        "acrobatics": 16,
        "stealth": 20
      },
      "languages": [
        "necril",
        "common"
      ],
      "defenses": {
        "immunities": [
          "death-effects",
          "disease",
          "paralyzed",
          "poison",
          "precision",
          "unconscious",
          "bleed"
        ],
        "resistances": [
          "all-damage 10 except force, ghost-touch, vitality, spirit"
        ],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "Vy2pPgrGJ3SguoOn",
          "name": "Shadow Hand",
          "bonus": 18,
          "damage": "2d10+6 void",
          "traits": [
            "finesse",
            "magical"
          ]
        }
      ],
      "actions": [
        {
          "id": "kppTcx5TylWkpfF1",
          "name": "Light Vulnerability",
          "kind": "passive",
          "description": "Attacks against the Pathfinder defender are treated as magical if made by a creature who is in magical light or with an object that is in magical light (such as from the Light spell).",
          "traits": []
        },
        {
          "id": "rn6en1AHFB9ns8VB",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "zadQdUq4eeiDSHSq",
          "name": "Shadow Spawn",
          "kind": "passive",
          "description": "When a creature's shadow is pulled free by Steal Shadow, it becomes a shadow spawn under the command of the shadow that created it. This Shadow Spawn doesn't have Steal Shadow. If the creature the shadow spawn was pulled from dies, the shadow spawn becomes a full-fledged, autonomous shadow. If the creature recovers from its enfeeblement, its shadow returns to it and the shadow spawn is extinguished.",
          "traits": []
        },
        {
          "id": "VB81WcGgMngyyh3E",
          "name": "Slink in Shadows",
          "kind": "passive",
          "description": "The Pathfinder defender can Hide or end its Sneak in a creature's or object's shadow.",
          "traits": []
        },
        {
          "id": "sslSR9PEr8cWdVop",
          "name": "Steal Shadow",
          "kind": "action",
          "description": "Requirements The Pathfinder defender hit a living creature with a shadow hand Strike on its previous action\nEffect The defender pulls at the target's shadow, making the creature Enfeebled 2 (Enfeebled 3 on a critical hit). This is cumulative with other enfeebled conditions from shadows, to a maximum of Enfeebled 4. If this increases a creature's enfeebled value to 3 or more, the target's shadow is separated from its body (see shadow spawn). The enfeebled value from Steal Shadow decreases by 1 every hour.",
          "traits": [
            "divine"
          ]
        }
      ],
      "spellcasting": [
        {
          "id": "UluC5rRvQl0yriAj",
          "name": "Divine Innate Spells",
          "tradition": "divine",
          "category": "innate",
          "attackModifier": 17,
          "saveDc": 25,
          "spells": [
            {
              "id": "sGyeCvgDJThi1CYg",
              "name": "Darkness",
              "rank": 2
            }
          ]
        }
      ]
    },
