    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Abendego's Squall (7-8)",
      "level": 9,
      "rarity": "unique",
      "size": "medium",
      "traits": [
        "environmental"
      ],
      "description": "Abendego's Squall leaps from the water. Its mouth opens to snap against any part of the ship that it can reach.",
      "armorClass": 26,
      "hitPoints": 70,
      "hardness": 0,
      "stealth": {
        "modifier": 16,
        "details": ""
      },
      "disable": "check (medicine, dc:23) (expert) to remove the harpoon, check (nature, dc:23) (trained), or check (intimidation, dc:23) (expert) to scare the orca away; two total successes are required to subdue the orca",
      "isComplex": true,
      "routine": "d The Abendego's Squall Leaps over the Snapdragon with each action. When it lands, it deals 4 damage to the Snapdragon. All creatures on the deck take 3d10+40 bludgeoning damage and must attempt a check (reflex, dc:28) save.\nCritical Success The target is unaffected.\nSuccess The target takes half damage.\nFailure The target takes full damage and is Clumsy 1 until the end of its next turn.\nCritical Failure The target takes double damage and is Clumsy 2 until the end of its next turn.\nSpeed 30 feet",
      "reset": "The Abendego's Squall returns to hunt down the Snapdragon after 8 hours.",
      "saves": {
        "fortitude": 15,
        "reflex": 21,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "xNPtZjddWwWKvvuU",
          "name": "Thar She Blows",
          "kind": "reaction",
          "description": "Trigger Abendego's Squall matches speed with the Snapdragon\nEffect The orca leaps across the Snapdragon and tears its main mast from the deck in the process. This deals 30 damage to the Snapdragon. All creatures on deck take 3d12+4 bludgeoning damage from the shrapnel and must attempt a check (reflex, dc:28, showDC:gm, basic) save. Abendego's Squall rolls initiative.",
          "traits": []
        }
      ]
    },
