    "translatableHash": "sha256:b3a5732fa750b381fafaa1c98ad3086125a13c9802ee4aa14745e107c05f84d9",
    "data": {
      "schemaVersion": 1,
      "name": "Captain Pitros Nanaeil",
      "level": 7,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "aiuvarin",
        "elf",
        "human",
        "humanoid"
      ],
      "description": "",
      "armorClass": 24,
      "hitPoints": 140,
      "speedFeet": 25,
      "perception": {
        "modifier": 18,
        "senses": []
      },
      "saves": {
        "fortitude": 15,
        "reflex": 18,
        "will": 15
      },
      "abilities": {
        "str": 4,
        "dex": 2,
        "con": 3,
        "int": 1,
        "wis": 0,
        "cha": 3
      },
      "skills": {
        "acrobatics": 11,
        "athletics": 15,
        "diplomacy": 14,
        "intimidation": 17,
        "society": 14,
        "stealth": 13,
        "survival": 11
      },
      "languages": [],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "ZKGKmMVNBF8CBnWl",
          "name": "Bloodletting Kukri",
          "bonus": 17,
          "damage": "2d6+7 slashing",
          "traits": [
            "agile",
            "finesse",
            "trip"
          ]
        },
        {
          "id": "wQf6uu8PeB8q6Cib",
          "name": "Scimitar",
          "bonus": 17,
          "damage": "2d6+7 slashing",
          "traits": [
            "forceful",
            "sweep"
          ]
        }
      ],
      "actions": [
        {
          "id": "QOT0UbjPYnIIySH9",
          "name": "+2 on All Saves Against Divine Magic",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "r0C8GUjKqvNfnURR",
          "name": "Aura of Command",
          "kind": "passive",
          "description": "30 feet. As captain of the Pure Legion, Nanaeil bolsters the lower-level legionnaires under his command, granting them a +1 status bonus to their attack rolls and +2 status bonus to their will saves.",
          "traits": [
            "aura",
            "emotion",
            "mental"
          ]
        },
        {
          "id": "jr5CFCk4BfGaQErO",
          "name": "Dual-Weapon Warrior",
          "kind": "passive",
          "description": "Pitros Nanaeil is highly trained in the art of wielding two weapons at once, preferring to wield the +1 striking scimitar in his main hand and the bloodletting kukri in his off-hand.",
          "traits": []
        },
        {
          "id": "2byeGaISmswuUpxU",
          "name": "May No Mortal Be Beholden",
          "kind": "passive",
          "description": "When Captain Nanaeil rolls a success on a save against an effect or spell from the divine tradition, they get a critical success instead.",
          "traits": []
        },
        {
          "id": "mTQ6VoPGwh2Y8JOc",
          "name": "Retributive Strike",
          "kind": "reaction",
          "description": "",
          "traits": []
        },
        {
          "id": "liIsPsXqsjby7neR",
          "name": "Twin Riposte",
          "kind": "reaction",
          "description": "Trigger A creature within your reach critically fails to Strike you.\nA clever parry with one weapon leaves your opponent open to an attack with the other weapon. Make a melee Strike or Disarm action against the triggering opponent.",
          "traits": []
        },
        {
          "id": "4LPO8MfLTdkoM9NV",
          "name": "Double Slice",
          "kind": "action",
          "description": "Nanaeil lashes out at his foe with both weapons. He makes two Strikes, one with each melee weapon, each using his current multiple attack penalty. Both Strikes must have the same target. If both attacks hit, combine their damage, then add any other applicable effects from both weapons. Precision damage is added only once. Combine the damage from both Strikes and apply resistances and weaknesses only once. This counts as two attacks when calculating his multiple attack penalty.",
          "traits": []
        },
        {
          "id": "NQMFcbNx3quS2mgG",
          "name": "Smite Divine",
          "kind": "passive",
          "description": "The Pure Legion's scimitars have been enchanted specifically to take down divine spellcasters. Melee Strikes against clerics, champions, and other creatures capable of casting divine spells do an additional 2d6 mental damage.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
