    "translatableHash": "sha256:0c2997069ad603ec21dda38faf05892e47f7424381d204a3f55b4514e88747d5",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Bloodmoon",
      "level": -1,
      "rarity": "unique",
      "size": "medium",
      "traits": [
        "haunt",
        "magical",
        "unholy"
      ],
      "description": "Bloodmoon is a naginata that can act on its own provided it is attuned to at least one creature.",
      "armorClass": 15,
      "hitPoints": 12,
      "hardness": 3,
      "stealth": {
        "modifier": 5,
        "details": ""
      },
      "disable": "Two successful check (religion, dc:15, options:disable-bloodmoon) or check (occultism, dc:15, options:disable-bloodmoon) checks, Dispel Magic (2nd rank; counteract DC 13)",
      "isComplex": true,
      "routine": "(3 actions) Bloodmoon uses its first action to fly up to 20 feet towards an opponent. It then makes two naginata strikes, each against a different foe.",
      "reset": "",
      "saves": {
        "fortitude": 8,
        "reflex": 2,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": [
          "holy 3"
        ]
      },
      "actions": [
        {
          "id": "w72xScDzGTN5XXIY",
          "name": "Object Immunities (Except Spirit)",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "xq5F6vFE3ZqlHhCt",
          "name": "Float",
          "kind": "reaction",
          "description": "Trigger Combat begins with the creature it is attuned to\nEffect The blade begins to float in the air, then rolls initiative.",
          "traits": [
            "magical"
          ]
        },
        {
          "id": "SxPuxDjMqJt4qaig",
          "name": "Prone to Monologuing",
          "kind": "passive",
          "description": "If a PC uses an action to taunt Bloodmoon with a successful check (deception, dc:13), check (diplomacy, dc:13), or check (intimidation, dc:13) check, Bloodmoon must spend an action monologuing on the next turn.",
          "traits": []
        }
      ]
    },
