    "translatableHash": "sha256:5ec68be96a36769a834e2d44d96201df7bc65bf77137c3ef0d5e4aa16440ffbe",
    "data": {
      "schemaVersion": 1,
      "name": "Zombie Leshy Horde",
      "level": 2,
      "rarity": "uncommon",
      "size": "gargantuan",
      "traits": [
        "leshy",
        "mindless",
        "plant",
        "troop",
        "undead",
        "unholy",
        "zombie"
      ],
      "description": "This shuffling mass of decaying flesh moves with dull but singular focus.\nNecromancers most often create these mindless undead as obedient, expendable servitors. Left to its own devices, a zombie seeks only to consume the living, stopping only when its rotting body can no longer hold together.",
      "armorClass": 15,
      "hitPoints": 60,
      "speedFeet": 20,
      "perception": {
        "modifier": 4,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 8,
        "reflex": 5,
        "will": 6
      },
      "abilities": {
        "str": 4,
        "dex": -2,
        "con": 3,
        "int": -5,
        "wis": 0,
        "cha": -2
      },
      "skills": {},
      "languages": [],
      "defenses": {
        "immunities": [
          "bleed",
          "death-effects",
          "disease",
          "paralyzed",
          "poison",
          "unconscious"
        ],
        "resistances": [],
        "weaknesses": [
          "area-damage 5",
          "vitality 5",
          "slashing 5",
          "splash-damage 2"
        ]
      },
      "attacks": [],
      "actions": [
        {
          "id": "VE0UqyozDof75tsl",
          "name": "Form Up",
          "kind": "action",
          "description": "",
          "traits": []
        },
        {
          "id": "yQzN4wExqO58Ssdr",
          "name": "Slow",
          "kind": "passive",
          "description": "A zombie leshy horde is permanently Slowed 1 and can't use reactions",
          "traits": []
        },
        {
          "id": "j3YK3rYte4HUEXXX",
          "name": "Troop Defenses",
          "kind": "passive",
          "description": "Thresholds 40 (3 segments), 20 (2 segments)",
          "traits": []
        },
        {
          "id": "xb36ZcB5nu2McDrU",
          "name": "Grave Tide",
          "kind": "passive",
          "description": "The zombie leshy horde is less organized than most troops. It can move into other creatures' spaces, and other creatures can move into its spaces. Its spaces are difficult terrain to other creatures.",
          "traits": []
        },
        {
          "id": "YNpN5FwvZ27Zfviz",
          "name": "Shambling Onslaught",
          "kind": "action",
          "description": "1 to 2\nFrequency once per round\nEffect The leshy zombies lash out at any enemies in their squares or within 5 feet (check (reflex, dc:15, basic, options:area-effect) save). The damage depends on the number of actions.\n1 1d8+4 bludgeoning damage\n2 1d8+8 bludgeoning damage",
          "traits": []
        },
        {
          "id": "ck37LN0pcQmPLf0a",
          "name": "Troop Movement",
          "kind": "passive",
          "description": "Whenever a troop Strides, it first Forms Up as a free action to condense into a 20-foot-by-20-foot area (minus any missing squares), then moves up to its Speed. This works just like a Gargantuan creature moving; for instance, if any square of the troop enters difficult terrain, the extra movement cost applies to the whole troop.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
