    "data": {
      "schemaVersion": 1,
      "name": "Dread Leshy Ghoul",
      "level": 5,
      "rarity": "uncommon",
      "size": "small",
      "traits": [
        "fungus",
        "ghoul",
        "leshy",
        "undead",
        "unholy"
      ],
      "description": "Few creatures are more ubiquitous to sinister locations such as lonely graveyards and ruined crypts than the flesh-eating undead known as ghouls.",
      "armorClass": 23,
      "hitPoints": 52,
      "speedFeet": 25,
      "perception": {
        "modifier": 10,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 12,
        "reflex": 14,
        "will": 10
      },
      "abilities": {
        "str": 3,
        "dex": 6,
        "con": 2,
        "int": -1,
        "wis": 3,
        "cha": 0
      },
      "skills": {
        "athletics": 10,
        "nature": 10,
        "stealth": 12,
        "survival": 13
      },
      "languages": [
        "common",
        "fey",
        "necril"
      ],
      "defenses": {
        "immunities": [
          "death-effects",
          "disease",
          "paralyzed",
          "poison",
          "unconscious",
          "bleed"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "XJHXZOImLOORwInT",
          "name": "Jaws",
          "bonus": 14,
          "damage": "1d10+5 piercing",
          "traits": [
            "finesse",
            "unarmed"
          ]
        },
        {
          "id": "A97t9GcQF8k7V7By",
          "name": "Claw",
          "bonus": 14,
          "damage": "1d8+5 slashing",
          "traits": [
            "agile",
            "finesse",
            "unarmed"
          ]
        },
        {
          "id": "A9wpwuBm0DDPWuzH",
          "name": "Spore Pod",
          "bonus": 14,
          "damage": "1d8+5 bludgeoning",
          "traits": []
        }
      ],
      "actions": [
        {
          "id": "MFt5sV6SiBXCs1fV",
          "name": "Constant Spells",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "Q56uznjD6F3ZIrgi",
          "name": "Rotten Burst",
          "kind": "passive",
          "description": "When a leshy ghoul dies, a burst of twisted primal void energy explodes from its body, restoring 2d8 healing Hit Points to each undead fungi or plant creature in a 30-foot type:emanation and killing all natural plants, though merely causing discomfort to creatures with the plant trait. This area is filled with rotten vegetation, becoming difficult terrain.",
          "traits": [
            "healing",
            "void"
          ]
        },
        {
          "id": "YzGXgyojcjzXVipz",
          "name": "Stench",
          "kind": "passive",
          "description": "10 feet. check (fortitude, dc:19, options:area-effect,inflicts:sickened,inflicts:slowed)",
          "traits": [
            "aura",
            "olfactory"
          ]
        },
        {
          "id": "dSMYHVMIltxeN4ms",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "OUwIUuX3HFB69lSp",
          "name": "Change Shape",
          "kind": "action",
          "description": "The leshy ghoul transforms into a Small giant mushroom or patch of fungi. This ability otherwise uses the effects of One with Plants.",
          "traits": [
            "concentrate",
            "polymorph",
            "primal"
          ]
        },
        {
          "id": "7RTjFlVzsxhjtwX4",
          "name": "Consume Flesh",
          "kind": "action",
          "description": "Requirements The ghoul is adjacent to the corpse of a creature that died within the last hour\nEffect The ghoul devours a chunk of the corpse and regains 3d6 healing Hit Points.",
          "traits": [
            "manipulate"
          ]
        },
        {
          "id": "pYrkU7D0zEWCIPMB",
          "name": "Forbidden Cravings",
          "kind": "passive",
          "description": "A creature can still eat and drink while sickened by this curse\nSaving Throw check (will, dc:22)\nStage 1 carrier with no ill effects (1 day)\nStage 2 2d6 void damage and the target is Sickened 1 until it consumes raw meat (1 day)\nStage 3 as stage 2\nStage 4 as stage 2 unless the target has consumed raw meat in the past 24 hours, then it takes 4d6 void damage and is Sickened 2 until it consumes raw meat\nStage 5 if the creature has eaten raw meat in the past 24 hours, it dies and rises as a ghoul, if not, it returns to stage 4",
          "traits": [
            "curse"
          ]
        },
        {
          "id": "jShRo5PDthe4aFDT",
          "name": "Ghoul Whispers",
          "kind": "action",
          "description": "Requirements A Grabbed, Paralyzed, Restrained, or Unconscious creature is within the ghoul's reach\nEffect The ghoul whispers dark thoughts and vile cravings into the creature's ears. The creature must save against the forbidden cravings curse.",
          "traits": [
            "auditory",
            "linguistic",
            "occult"
          ]
        },
        {
          "id": "Eio9qRZi4Wxz6XXD",
          "name": "Grave Knowledge",
          "kind": "passive",
          "description": "Frequency once per hour\nEffect The ghoul calls upon knowledge it retains from one creature it has consumed in the past 7 days. The ghoul attempts a skill check using a skill in which the consumed creature was trained (if it's unclear whether the creature was trained, the GM decides). The ghoul is treated as trained and uses the high skill modifier for the ghoul's level. This takes the same amount of actions or time as usual for the check.\nThe ghoul can instead automatically learn something specific known by a creature it consumed in the last 7 days, like the location of a Hidden treasure or the name of a loved one. The ghoul can do this only once for a given creature, no matter how much of its flesh the ghoul consumed.",
          "traits": [
            "occult"
          ]
        },
        {
          "id": "kJUApzF9beBQy9ZK",
          "name": "Spore Cloud",
          "kind": "action",
          "description": "A leshy ghoul can unleash a cloud of spores that irritates the eyes and throats of non-fungus creatures in a 15-foot type:emanation. Each creature must succeed at a check (fortitude, dc:19, options:area-effect,damaging-effect) save or take 1 persistent poison damage. A creature has its vision reduced as long as the persistent damage continues and can see only within 20 feet.",
          "traits": []
        },
        {
          "id": "rnZiI5m7zQDyQeSG",
          "name": "Spores",
          "kind": "passive",
          "description": "A creature that takes damage from a fungus leshy's spore pod Strike must attempt a saving throw with the same DC and effect as its Spore Cloud ability.",
          "traits": []
        },
        {
          "id": "rvraBop9oOSwcjkq",
          "name": "Swift Leap",
          "kind": "action",
          "description": "The ghoul jumps up to half its Speed. This movement doesn't trigger reactions.",
          "traits": [
            "move"
          ]
        },
        {
          "id": "NaSXwkNPzNz5tsgw",
          "name": "Grab",
          "kind": "action",
          "description": "",
          "traits": []
        }
      ],
      "spellcasting": [
        {
          "id": "GK587sU5NS4aS650",
          "name": "Primal Innate Spells",
          "tradition": "primal",
          "category": "innate",
          "attackModifier": 11,
          "saveDc": 19,
          "spells": [
            {
              "id": "d4Fo6jCvOoQlXVaP",
              "name": "Speak with Plants (Constant, Fungi Only)",
              "rank": 3
            }
          ]
        }
      ]
    },
