    "data": {
      "schemaVersion": 1,
      "name": "Oozeshard",
      "level": 8,
      "rarity": "common",
      "size": "huge",
      "traits": [
        "mythic",
        "ooze"
      ],
      "description": "",
      "armorClass": 16,
      "hitPoints": 180,
      "speedFeet": 30,
      "perception": {
        "modifier": 10,
        "senses": [
          "motion-sense-imprecise-60"
        ]
      },
      "saves": {
        "fortitude": 20,
        "reflex": 7,
        "will": 16
      },
      "abilities": {
        "str": 7,
        "dex": -5,
        "con": 7,
        "int": -2,
        "wis": 0,
        "cha": -5
      },
      "skills": {
        "athletics": 20
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "acid",
          "unconscious",
          "critical-hits",
          "electricity"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [],
      "actions": [
        {
          "id": "9IQj88Hkj1UAEeaG",
          "name": "Armored Apotheosis",
          "kind": "passive",
          "description": "When it is first encountered, the oozeshard is in a lumpy, vaguely spherical ooze form. When it takes damage from any weapon attack, it suddenly reshapes, taking a form almost identical to the dead deity Gorum. The ooze hardens into armored plates (increasing its AC by +8) and its pseudopod transforms into a massive, acid-dripping greatsword. While in this form, it loses its pseudopod attack and its immunity to bludgeoning and precision damage. It cannot use its constrict or engulf abilities, and any creature currently engulfed by it is spat out into an adjacent random square, taking 1d4 acid damage] damage. It gains the Reactive Strike reaction. If it is critically hit by a Strike or critically fails a save against an effect that deals Hit Point damage to it, the oozeshard reverts back into its ooze form.",
          "traits": []
        },
        {
          "id": "aSMT0peR3dmWXujl",
          "name": "Reactive Strike (Armored Apotheosis Only)",
          "kind": "reaction",
          "description": "",
          "traits": []
        },
        {
          "id": "wWPEZvZinFCGsmW2",
          "name": "Constrict (Ooze Form Only)",
          "kind": "action",
          "description": "1d8+7 bludgeoning damage], check (fortitude, dc:27, basic)",
          "traits": []
        },
        {
          "id": "NFiC1mOQkGXNZK6F",
          "name": "Engulf (Ooze Form Only)",
          "kind": "action",
          "description": "check (reflex, dc:23, options:damaging-effect,inflicts:grabbed,inflicts:slowed), 2d8 acid damage, Escape DC 23, Rupture 20",
          "traits": []
        },
        {
          "id": "tywbosK5iMu0FmPc",
          "name": "Gorumite Echoes",
          "kind": "passive",
          "description": "While in its armored apotheosis form, the oozeshard deals an additional 1d6 bleed damage and makes the target Off-Guard for 1 round when it critically hits with its greatsword.",
          "traits": []
        },
        {
          "id": "QEOgW56JFwhtqtP4",
          "name": "Spawn Oozeshardling Node",
          "kind": "passive",
          "description": "Whenever the oozeshard takes 45 or more damage from a single attack, it spawns an oozeshardling node in an adjacent square. The oozeshardling node's electric pulse reaction immediately activates, and then the oozeshardling node enters initiative at the bottom of the current initiative count.",
          "traits": []
        },
        {
          "id": "nYlGCZd6SfxXi9ZM",
          "name": "Grab",
          "kind": "action",
          "description": "",
          "traits": []
        }
      ],
      "spellcasting": []
    },
