    "translatableHash": "sha256:e9e631a8ae5cffb929aaea5fd76b86d53c4e8f742b1784ff4807bc0fa7265568",
    "data": {
      "schemaVersion": 1,
      "name": "Shadowpact Shadow",
      "level": 7,
      "rarity": "rare",
      "size": "medium",
      "traits": [
        "incorporeal",
        "undead",
        "unholy"
      ],
      "description": "Shadows that spend long amounts of time on the Netherworld and absorb its magic become greater shadows.\nThe mysterious undead known as shadows lurk in dark places and feed on those who stray too far from the light.",
      "armorClass": 24,
      "hitPoints": 75,
      "speedFeet": 0,
      "perception": {
        "modifier": 14,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 11,
        "reflex": 18,
        "will": 15
      },
      "abilities": {
        "str": -5,
        "dex": 5,
        "con": 0,
        "int": 0,
        "wis": 2,
        "cha": 4
      },
      "skills": {
        "acrobatics": 16,
        "stealth": 20
      },
      "languages": [
        "necril"
      ],
      "defenses": {
        "immunities": [
          "death-effects",
          "disease",
          "paralyzed",
          "poison",
          "precision",
          "unconscious",
          "bleed"
        ],
        "resistances": [
          "all-damage 10 except force, ghost-touch, vitality, spirit"
        ],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "Vy2pPgrGJ3SguoOn",
          "name": "Shadow Hand",
          "bonus": 18,
          "damage": "2d10+6 void",
          "traits": [
            "finesse",
            "magical"
          ]
        }
      ],
      "actions": [
        {
          "id": "kppTcx5TylWkpfF1",
          "name": "Light Vulnerability",
          "kind": "passive",
          "description": "Attacks against the shadow are treated as magical if made by a creature who is in magical light or with an object that is in magical light (such as from the Light spell).",
          "traits": []
        },
        {
          "id": "rn6en1AHFB9ns8VB",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "6PZpeNlYGVEoZJmo",
          "name": "Deadly Striker",
          "kind": "passive",
          "description": "The shadowpact shadow deals an additional 1d6 precision damage on their next Strike whenever they use an action to Stride 10 or more feet.",
          "traits": []
        },
        {
          "id": "zadQdUq4eeiDSHSq",
          "name": "Greater Shadow Spawn",
          "kind": "passive",
          "description": "When a creature's shadow is pulled free by Steal Shadow, it becomes a greater shadow spawn under the command of the shadow that created it, using these statistics without Deadly Striker, Steal Shadow, or Unimpeded. This shadow spawn is incurably Clumsy 2. If the creature the shadow spawn was pulled from dies, the shadow spawn becomes a full-fledged, autonomous greater shadow, gaining Steal Shadow and losing the clumsy condition. If the creature recovers from its enfeeblement, its shadow returns to it and the shadow spawn is extinguished.",
          "traits": []
        },
        {
          "id": "VB81WcGgMngyyh3E",
          "name": "Slink in Shadows",
          "kind": "passive",
          "description": "The shadow can Hide or end its Sneak in a creature's or object's shadow.",
          "traits": []
        },
        {
          "id": "sslSR9PEr8cWdVop",
          "name": "Steal Shadow",
          "kind": "action",
          "description": "Requirements The shadow hit a living creature with a shadow hand Strike on its previous action\nEffect The shadow pulls at the target's shadow, making the creature Enfeebled 2 (Enfeebled 3 on a critical hit). This is cumulative with other enfeebled conditions from shadows, to a maximum of enfeebled 4. If this increases a creature's enfeebled value to 3 or more, the target's shadow is separated from its body (see shadow spawn). The enfeebled value from Steal Shadow decreases by 1 every hour.",
          "traits": [
            "divine"
          ]
        },
        {
          "id": "c9FbrbyXGCZAqGN8",
          "name": "Unimpeded",
          "kind": "action",
          "description": "Frequency once per day\nEffect The shadowpact shadow automatically ends one effect that would give them a circumstance penalty to Speed. When they attempt to Escape an effect that has them Immobilized, Grabbed, or Restrained, they automatically succeed.",
          "traits": []
        }
      ],
      "spellcasting": [
        {
          "id": "UluC5rRvQl0yriAj",
          "name": "Divine Innate Spells",
          "tradition": "divine",
          "category": "innate",
          "attackModifier": 17,
          "saveDc": 25,
          "spells": [
            {
              "id": "sGyeCvgDJThi1CYg",
              "name": "Darkness (At Will)",
              "rank": 2
            }
          ]
        }
      ]
    },
