    "data": {
      "schemaVersion": 1,
      "name": "Deep Manifestation of Nightmare",
      "level": 9,
      "rarity": "uncommon",
      "size": "large",
      "traits": [
        "aberration"
      ],
      "description": "",
      "armorClass": 27,
      "hitPoints": 160,
      "speedFeet": 25,
      "perception": {
        "modifier": 21,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 21,
        "reflex": 15,
        "will": 18
      },
      "abilities": {
        "str": 6,
        "dex": 2,
        "con": 6,
        "int": 0,
        "wis": 3,
        "cha": 6
      },
      "skills": {
        "acrobatics": 17,
        "athletics": 20,
        "intimidation": 20,
        "occultism": 15
      },
      "languages": [
        "aklo",
        "common"
      ],
      "defenses": {
        "immunities": [
          "emotion"
        ],
        "resistances": [
          "mental 10"
        ],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "CZVwx0RpcoRPib7C",
          "name": "Morphic Limb",
          "bonus": 21,
          "damage": "2d10+12 bludgeoning",
          "traits": [
            "magical",
            "versatile-p",
            "versatile-s"
          ]
        },
        {
          "id": "pwxu64B6dtIIC1oy",
          "name": "Nightmare Vision",
          "bonus": 19,
          "damage": "4d6+7 mental",
          "traits": []
        }
      ],
      "actions": [
        {
          "id": "NahLYoW0e1IzE7i4",
          "name": "Reactive Strike",
          "kind": "reaction",
          "description": "",
          "traits": []
        },
        {
          "id": "6jIvPGI89DjHhbbB",
          "name": "Constrict Mind",
          "kind": "action",
          "description": "The manifestation of nightmare deals 2d6+9 mental damage to any number of creatures that are Grabbed or Restrained by it (check (will, dc:28, basic) save). Creatures that fail the save are Frightened 1, or Frightened 2 on a critical failure.",
          "traits": []
        },
        {
          "id": "G2oXTAPyRAALRTFA",
          "name": "Morphic Limb",
          "kind": "passive",
          "description": "A manifestation of nightmare can form up to 8 morphic limbs at the same time. These limbs are constantly shifting their features according to the manifestation's whims, becoming fists, claws, pincers, blades, and anything else that it can imagine.",
          "traits": []
        },
        {
          "id": "RwOpOaB417q5eIKE",
          "name": "Recurring Nightmare",
          "kind": "passive",
          "description": "A Frightened creature that is being Grabbed by a manifestation of nightmare can't reduce the value of its frightened condition below 1 until it Escapes.",
          "traits": []
        },
        {
          "id": "IT0KNDfWpGkEg7VM",
          "name": "Unnerving Echo",
          "kind": "passive",
          "description": "If the manifestation of nightmare critically hits with a nightmare vision Strike, the target is Frightened 1.",
          "traits": []
        },
        {
          "id": "6FHQydljmAk87BHy",
          "name": "Grab",
          "kind": "action",
          "description": "",
          "traits": []
        }
      ],
      "spellcasting": []
    },
