    "sourceHash": "sha256:4c820167c03e130b044283164f80fba00b8fb23d91e110a8b8b32b8160d65c06",
    "translatableHash": "sha256:382de5920d340ba488e27bf9cf7c4e0ad2b36fc3a02558ab17436df004785cd8",
    "data": {
      "schemaVersion": 1,
      "name": "Gruasha",
      "level": 11,
      "rarity": "uncommon",
      "size": "large",
      "traits": [
        "giant",
        "humanoid",
        "shadow"
      ],
      "description": "Shadow giants are natives of the Netherworld, where they have dwelled in perpetual twilight for millennia. They live in familiar groups and uphold a nomadic way of life as they roam across ancestral lands between shadowy forests and misty chasms. These hunter-gatherers pass down lore through oral histories, conduct pilgrimages to unholy ziggurats of black stone, and bathe in the blood of their long-standing foes, including rival shadow giant clans and fiends of the Netherworld intent on enslaving their kind.\nStanding 15 feet tall, with gray skin and hair only a shade lighter, shadow giants are fearsome foes with a well-earned reputation as zealous warmongers and ruthless combatants. They rarely interact with outsiders, though they may treat with proven warriors who show the giants the respect and deference they feel they deserve.\nGiants are massive humanoid creatures who live in remote regions throughout the world. They vary widely but are united in their hunger, requiring sustenance of their own element along with the feasts one would expect from such a massive humanoid. Although a simple matter for some giants, more esoteric types find this need a harsh reality. While a massive fistful of ice or snow alongside their meal will satisfy a frost giant, shadow giants hunger for the coagulated shadows of the Netherworld.",
      "armorClass": 31,
      "hitPoints": 195,
      "speedFeet": 35,
      "perception": {
        "modifier": 24,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 18,
        "reflex": 24,
        "will": 20
      },
      "abilities": {
        "str": 8,
        "dex": 5,
        "con": 3,
        "int": 0,
        "wis": 5,
        "cha": 2
      },
      "skills": {
        "acrobatics": 22,
        "athletics": 23,
        "intimidation": 19,
        "stealth": 22
      },
      "languages": [
        "common",
        "jotun",
        "shadowtongue"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "zgKk3c4d3SCNJutG",
          "name": "Spiked Chain",
          "bonus": 24,
          "damage": "2d8+16 slashing",
          "traits": [
            "disarm",
            "reach-10",
            "trip"
          ]
        },
        {
          "id": "HaXqTHQH97u8nuJK",
          "name": "Fist",
          "bonus": 23,
          "damage": "3d6+16 bludgeoning",
          "traits": [
            "agile",
            "nonlethal",
            "reach-10",
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "FiN1vHXOR20gVKDC",
          "name": "Reactive Strike",
          "kind": "reaction",
          "description": "",
          "traits": []
        },
        {
          "id": "WsGuoYeAA0yWHOXE",
          "name": "Pall of Shadow",
          "kind": "passive",
          "description": "When a shadow giant hits with a melee attack, the target must succeed at a check (fortitude, dc:27) save or become Drained 1 and take a –1 status penalty to Perception checks involving sight as long as they remain drained. On a critical failure, this condition doesn't heal naturally and can be removed only with magic.",
          "traits": [
            "divine",
            "shadow"
          ]
        },
        {
          "id": "CFQjHuIFlshnvM7H",
          "name": "Shadow Chain",
          "kind": "action",
          "description": "Shadows extend the giant's chain as they make a spiked chain Strike, increasing their reach to 60 feet for that Strike. If this hits, the target must succeed at a check (will, dc:30) save or be teleported to an empty space within the shadow giant's normal reach.",
          "traits": [
            "divine",
            "shadow",
            "teleportation"
          ]
        },
        {
          "id": "PDPYyeFFpfksUoXK",
          "name": "Shadowcloak",
          "kind": "action",
          "description": "The shadow giant gains the effect of the Blur spell for 1 minute or until they are exposed to direct sunlight, whichever comes first.",
          "traits": [
            "divine",
            "shadow"
          ]
        }
      ],
      "spellcasting": []
    },
