    "sourceHash": "sha256:fb4cfacc00e315bfe43666ea228e9cdf7790a96bd21954a05550cfdd428fd658",
    "translatableHash": "sha256:72daf5c0228b7fccdb670d11208975e4d0fe75a21e9290bcc744dff5084e3de3",
    "data": {
      "schemaVersion": 1,
      "name": "Cackling Skull",
      "level": 6,
      "rarity": "rare",
      "size": "tiny",
      "traits": [
        "evil",
        "undead",
        "unholy"
      ],
      "description": "Some beheaded are raised with their mental faculties mostly intact. These clever undead often provoke their victims into foolishly giving chase or harming themselves.\nBeheaded are disembodied floating heads transformed into undead. They are natural candidates for a necromancer's \"project minion,\" due to the inexpensive cost of creation and endlessly customizable nature. In any lair occupied for long by practicing necromancers, it isn't uncommon to find a handful of floating heads roaming about, each exhibiting completely different characteristics and even degrees of expertise in their creation.",
      "armorClass": 24,
      "hitPoints": 90,
      "speedFeet": 15,
      "perception": {
        "modifier": 15,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 12,
        "reflex": 16,
        "will": 13
      },
      "abilities": {
        "str": 1,
        "dex": 5,
        "con": 1,
        "int": 0,
        "wis": 4,
        "cha": 2
      },
      "skills": {
        "acrobatics": 13,
        "intimidation": 13
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "death-effects",
          "disease",
          "paralyzed",
          "poison",
          "unconscious",
          "bleed",
          "mental"
        ],
        "resistances": [],
        "weaknesses": [
          "vitality 5"
        ]
      },
      "attacks": [
        {
          "id": "f303t130pkbopzk0",
          "name": "Jaws",
          "bonus": 16,
          "damage": "2d10+5 piercing",
          "traits": [
            "agile",
            "finesse",
            "reach-0",
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "qxv9k072qjlqqrmv",
          "name": "Bite Back",
          "kind": "reaction",
          "description": "Trigger The cackling skull is attacked by a creature within their reach\nEffect The cackling skull makes a jaws Strike against that creature.",
          "traits": []
        },
        {
          "id": "apXBdiwzInrE6nhf",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "je6z12w9bwlsz6kk",
          "name": "Incessant Goading",
          "kind": "action",
          "description": "The skull chooses one creature within 60 feet and antagonizes it mercilessly. The target must attempt a check (will, dc:24) save to resist the effect.\nCritical Success The target is unaffected and temporarily immune for 1 minute.\nSuccess The target is unaffected.\nFailure The target is Off-Guard for 1 round. On its next turn, if the taunting skull is within the target's reach, the target wildly attacks the taunting skull as many times as possible.\nCritical Failure As failure, but the target also immediately performs a Strike against itself; this Strike doesn't take any actions.",
          "traits": [
            "auditory",
            "emotion",
            "incapacitation",
            "mental"
          ]
        }
      ],
      "spellcasting": []
    },
