    "sourceHash": "sha256:09b2176ed94a0fd2a80abb7741a330b47da8e5ebb559a6d71c78854b5a763e19",
    "translatableHash": "sha256:3e0fecea5ea040f85d9856b404af51154377dbc9471b3176cb6a4000c47af54c",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Thorns of the Rose Pit",
      "level": 3,
      "rarity": "unique",
      "size": "large",
      "traits": [
        "magical",
        "mechanical",
        "trap"
      ],
      "description": "Decorated smooth-hewn flagstone flooring gives way along hidden seams to a 20-foot square, 25-foot-deep pit festooned with spikes and blades of petrified wood in the darkness below.",
      "armorClass": 19,
      "hitPoints": 46,
      "hardness": 12,
      "stealth": {
        "modifier": 13,
        "details": "(or 0 if the trap door is disabled or broken) or Detect Magic"
      },
      "disable": "check (thievery, dc:20) (trained) to disable the trap door mechanism",
      "isComplex": false,
      "routine": "",
      "reset": "Creatures can still fall into the trap, but the trap door must be reset manually for the trap to become hidden again.",
      "saves": {
        "fortitude": 8,
        "reflex": 5,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "hGQaUcNONfV9QADG",
          "name": "Pitfall",
          "kind": "reaction",
          "description": "Trigger A creature walks onto the trap door\nEffect The triggering creature falls in and takes falling damage (typically 10 bludgeoning damage). That creature can use the Grab an Edge reaction to avoid falling.\nWhen creatures fall into the pit, the petrified wood spikes along the floor grow to attempt to plunge into the triggering creature.",
          "traits": []
        }
      ]
    },
