      "actions": [
        {
          "id": "xkshjfEojPnex72N",
          "name": "Rally",
          "kind": "reaction",
          "description": "Trigger A named ally of Petra's flees combat\nEffect When spirits flag, Petra barks a rallying cry to her troops. When a named ally like Marius flees the field of battle, each Hellknight or agent of Thrune ally who hears this cry becomes bolstered by Petra's presence. They gain a +1 circumstance bonus to their AC and saving throws until the end of Petra's next turn.\nEffect: Rally",
          "traits": [
            "auditory",
            "emotion",
            "linguistic"
          ]
        },
        {
          "id": "Ecpn6EeMASqufNmi",
          "name": "Reactive Strike",
          "kind": "reaction",
          "description": "",
          "traits": []
        },
        {
          "id": "XnJxfwZ6ejdiPiqa",
          "name": "Commander's Orders",
          "kind": "action",
          "description": "Petra issues a command to hasten her direct reports. Each Hellknight or agent of Thrune ally who hears and understands this command becomes Quickened until the end of that ally's next turn but can use the extra action only to Step or Stride.",
          "traits": [
            "auditory",
            "fear",
            "linguistic"
          ]
        },
        {
          "id": "CWPNSWX3OrGnmjK9",
          "name": "Experienced Swordsmith",
          "kind": "passive",
          "description": "Petra has spent years training with a longsword in hand. When she critically succeeds at a Strike with her longsword, the target is Off-Guard until the beginning of her next turn.",
          "traits": []
        }
      ],
      "spellcasting": []
