    "translatableHash": "sha256:cb28f6663379d50602a30b2e2977cc74fa2c9f2c81942f583b9346ed558660fd",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Handheld Quaker",
      "level": 2,
      "rarity": "common",
      "size": "large",
      "traits": [
        "mechanical",
        "trap"
      ],
      "description": "This small toy-like device has a hidden mechanism meant to be activated by the user, but the centuries have eroded its magical-mechanical components to the point that they activate at the slightest touch.",
      "armorClass": 15,
      "hitPoints": 32,
      "hardness": 9,
      "stealth": {
        "modifier": 10,
        "details": ""
      },
      "disable": "check (thievery, dc:18) (trained) to deactivate the mechanism; check (crafting, dc:16) (trained) to identify and repair the problem components; two successes are required to disable the hazard.",
      "isComplex": true,
      "routine": "At its initiative, to determine what the quaker does, roll 1d4 and consult the following table:\n1: No action\n2: A small quake: the terrain in a 10-foot type:emanation centered on the quaker shakes briefly. A creature in an affected square is knocked Prone (check (reflex, dc:18) save).\n3: A medium quake: the terrain within the vault shakes constantly, transforming it into difficult terrain until its next turn. A creature in an affected square is knocked prone and takes 1d10 bludgeoning damage from the fall (check (reflex, dc:18, basic) save).\n4: A great quake: the terrain within the vault moves in waves, transforming it into greater difficult terrain until its next turn. A creature in an affected square is violently slammed to the ground, knocked prone, and takes 1d10+4 bludgeoning damage (check (reflex, dc:20, basic) save).",
      "reset": "The trap deactivates and resets if 1 minute passes without a creature being within 5' of the handheld quaker.",
      "saves": {
        "fortitude": 12,
        "reflex": 5,
        "will": 0
      },
      "defenses": {
        "immunities": [
          "critical-hits",
          "precision"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "BKwyqCSkj5RBfLVm",
          "name": "Quake!",
          "kind": "reaction",
          "description": "Trigger A creature moves into a space with the handheld quaker or interacts with it\nEffect The handheld quaker vibrates visibly and rolls initiative.",
          "traits": []
        },
        {
          "id": "y25H9mfqjAEjl1NC",
          "name": "Shaking Earth",
          "kind": "passive",
          "description": "A creature within difficult terrain created by the quaker takes a –2 circumstance penalty to Reflex saves and actions with the Manipulate trait, including Disable Device.",
          "traits": []
        }
      ]
    },
