    "data": {
      "schemaVersion": 1,
      "name": "The Caretaker",
      "level": 3,
      "rarity": "unique",
      "size": "medium",
      "traits": [
        "ghost",
        "incorporeal",
        "spirit",
        "undead",
        "unholy"
      ],
      "description": "",
      "armorClass": 18,
      "hitPoints": 20,
      "speedFeet": 25,
      "perception": {
        "modifier": 12,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 9,
        "reflex": 12,
        "will": 9
      },
      "abilities": {
        "str": -5,
        "dex": 4,
        "con": 0,
        "int": 3,
        "wis": 2,
        "cha": 0
      },
      "skills": {
        "stealth": 7
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "bleed",
          "death-effects",
          "disease",
          "paralyzed",
          "poison",
          "precision",
          "unconscious"
        ],
        "resistances": [
          "all-damage 4 except force, ghost-touch, spirit, vitality"
        ],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "y9dOy1aSF7M2CnB6",
          "name": "Ghostly Hand",
          "bonus": 11,
          "damage": "2d4+2 void",
          "traits": [
            "agile",
            "finesse",
            "magical"
          ]
        }
      ],
      "actions": [
        {
          "id": "sPnji5oOyb1NaOAA",
          "name": "Site Bound",
          "kind": "passive",
          "description": "A typical ghost can stray only a short distance from where it was killed or the place it haunts. A typical limit is 120 feet. Some ghosts are instead bound to a room, building, item, or creature that was special to it rather than a location.",
          "traits": []
        },
        {
          "id": "z294ZgeVIeaVpYTW",
          "name": "Rejuvenation",
          "kind": "passive",
          "description": "When defeated, The Caretaker returns in 1 hour, unless he is released with a check (religion, dc:22) check or convinced that the PCs are friendly with a check (diplomacy, dc:16) check.",
          "traits": [
            "divine"
          ]
        },
        {
          "id": "QOJVxCIDhVyumQUv",
          "name": "Void Healing",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "U405VDoNIkMc9Zva",
          "name": "Inhabit Object",
          "kind": "action",
          "description": "The Caretaker possess an object of size Large or smaller within 20 feet, making it an animated object (maximum level 1). If the target object is being held by a creature, the bearer can attempt a check (will, dc:16) save to prevent the possession. The possession ends when the object is destroyed or the Caretaker leaves it. At this point, the Caretaker reappears in the object's square and can't Inhabit an Object again for 1d4.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
