    "sourceHash": "sha256:1bb3197c48d5b0e605c989858f470fa98b55fcccc2eaf65ab95f1286ca2315d5",
    "translatableHash": "sha256:3bb7b8e4b5d9e6125d84ced908e4dc6ce67276c4984ccdd856701b734b0eaef3",
    "data": {
      "schemaVersion": 1,
      "name": "Elite Concentrated Congealed Magic",
      "level": 5,
      "rarity": "uncommon",
      "size": "large",
      "traits": [
        "mindless",
        "ooze"
      ],
      "description": "Tomb jellies are animate masses of protoplasm with a sickly combination of yellow, gray, and black hues. Their acidic bodies dissolve flesh but leave other materials, including a victim's gear and bones, intact. Some ancient cultures entombed bodies in stone sarcophagi with tomb jellies to allow the ooze to break down the flesh and clean and polish the bones.\nSlimes, molds, and other oozes can be found in dank dungeons and shadowed forests. While not necessarily evil, some grow to enormous sizes and have insatiable appetites.",
      "armorClass": 12,
      "hitPoints": 150,
      "speedFeet": 15,
      "perception": {
        "modifier": 7,
        "senses": [
          "motion-sense-60"
        ]
      },
      "saves": {
        "fortitude": 15,
        "reflex": 4,
        "will": 7
      },
      "abilities": {
        "str": 6,
        "dex": -5,
        "con": 6,
        "int": -5,
        "wis": 0,
        "cha": -5
      },
      "skills": {
        "athletics": 13
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "acid",
          "visual",
          "bleed",
          "critical-hits",
          "precision",
          "slashing",
          "unconscious",
          "void"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "2vNOWipXsprXmJET",
          "name": "Pseudopod",
          "bonus": 15,
          "damage": "1d8+6 bludgeoning; 1d6 void",
          "traits": [
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "rKZevHCH4PMtuj6Z",
          "name": "Motion Sense",
          "kind": "passive",
          "description": "Concentrated congealed magic can feel nearby motion through vibration and air movement.",
          "traits": []
        },
        {
          "id": "BzmoXVcXW8cazBe5",
          "name": "Bound in Death",
          "kind": "action",
          "description": "The concentrated congealed magic splatters some of its substance on a willing undead creature within its reach. The target regains 3 healing HP, and its melee Strikes get the benefits of shadow curse until the end of its next turn.\nEffect: Bound in Death",
          "traits": [
            "healing",
            "void"
          ]
        },
        {
          "id": "snySLSbjtHjATjFS",
          "name": "Flesh-dissolving Acid",
          "kind": "passive",
          "description": "A tomb jelly's acid damages only flesh.",
          "traits": []
        },
        {
          "id": "A872unbEeSXWQvTn",
          "name": "Shadow Curse",
          "kind": "passive",
          "description": "A creature hit by concentrated congealed magic's pseudopod takes 1d6 persistent void damage. If the creature dies while it has this persistent damage, its corpse is affected by Peaceful Rest, except the concentrated congealed magic can still dissolve its flesh.",
          "traits": [
            "curse",
            "divine",
            "void"
          ]
        }
      ],
      "spellcasting": []
    },
