      "attacks": [
        {
          "id": "VESnbFKYoruhuMSI",
          "name": "Rotcarver",
          "bonus": 17,
          "damage": "1d10+9 piercing; 1d8 void",
          "traits": [
            "magical"
          ]
        },
        {
          "id": "jKUq1E06sE0REB63",
          "name": "Fist",
          "bonus": 16,
          "damage": "1d4+9 bludgeoning",
          "traits": [
            "agile",
            "nonlethal",
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "0iKagCxTDFf1p9SV",
          "name": "Bog Rot",
          "kind": "passive",
          "description": "This affliction can't be reduced below stage 1, nor can the damage from it be healed, until it's successfully treated with remove curse or a similar effect; the affliction can then be removed as normal for a disease. A creature killed by bog rot melts into a noxious sludge and can't be resurrected except by a 7th-rank Resurrect ritual or similar magic\nSaving Throw check (fortitude, dc:21)\nStage 1 carrier with no ill effect (1 minute)\nStage 2 3d6 void damage and Clumsy 1 (1 day)",
          "traits": [
            "curse",
            "disease",
            "divine",
            "void"
          ]
        },
        {
          "id": "OBpiSvaf3hSmsvXL",
          "name": "Deskari's Rage",
          "kind": "action",
          "description": "Amriya tightens hir group on Rotcarver and attempts a powerful Strike against hir enemy. On a success, ze deals an additional 1d10 piercing damage.",
          "traits": []
        },
        {
          "id": "cgZ2ARrsevGLRMN7",
          "name": "Rot and Ruin",
          "kind": "action",
          "description": "Amriya's mouth opens, spewing forth a vapor that triggers rot and decay. All creatures within a 20-foot type:emanation must attempt a check (fortitude, dc:25, basic, options:area-effect,damaging-effect,inflicts:sickened) saving throw or take 3d12 void damage. On a critical failure, creatures are Sickened 1 for 1 minute.",
          "traits": []
        }
      ],
