    "data": {
      "schemaVersion": 1,
      "name": "Levaloch (PFS 6-17)",
      "level": 7,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "devil",
        "evil",
        "fiend",
        "lawful",
        "unholy"
      ],
      "description": "Fearsome giants of jagged iron, levalochs serve in the armies of Hell as potent warriors and tenacious hunters-creatures of absolute discipline endlessly obedient to diabolical tyrants.\nThere are countless legions of lawful fiends in the nine layers of Hell, warring against the celestial planes and scouring the Material Plane for souls to corrupt.",
      "armorClass": 25,
      "hitPoints": 105,
      "speedFeet": 30,
      "perception": {
        "modifier": 16,
        "senses": [
          "greater-darkvision"
        ]
      },
      "saves": {
        "fortitude": 17,
        "reflex": 14,
        "will": 12
      },
      "abilities": {
        "str": 6,
        "dex": 3,
        "con": 4,
        "int": 2,
        "wis": 3,
        "cha": 1
      },
      "skills": {
        "acrobatics": 14,
        "athletics": 17,
        "intimidation": 13,
        "religion": 14
      },
      "languages": [
        "diabolic",
        "empyrean",
        "common"
      ],
      "defenses": {
        "immunities": [
          "fire",
          "death-effects",
          "disease",
          "doomed",
          "drained",
          "fatigued",
          "healing",
          "nonlethal-attacks",
          "paralyzed",
          "poison",
          "sickened",
          "unconscious",
          "void"
        ],
        "resistances": [
          "physical 5 except silver"
        ],
        "weaknesses": [
          "holy 5"
        ]
      },
      "attacks": [
        {
          "id": "xGpHtG4FKoXUAvFz",
          "name": "Trident",
          "bonus": 19,
          "damage": "2d8+9 piercing; 1d6 spirit",
          "traits": [
            "magical",
            "unholy"
          ]
        },
        {
          "id": "a8Oke93EjcLb3CyD",
          "name": "Trident",
          "bonus": 16,
          "damage": "2d8+9 piercing; 1d6 spirit",
          "traits": [
            "magical",
            "thrown-20",
            "unholy"
          ]
        },
        {
          "id": "5mZBnyI8jN8hRDpC",
          "name": "Barbed Net",
          "bonus": 16,
          "damage": "",
          "traits": [
            "magical",
            "unholy"
          ]
        }
      ],
      "actions": [
        {
          "id": "Mfyiq7MrkDXVAE1n",
          "name": "Greater Darkvision",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "O5Ub4Pr4nhdrG6Xy",
          "name": "Telepathy 100 feet",
          "kind": "passive",
          "description": "",
          "traits": [
            "aura",
            "magical"
          ]
        },
        {
          "id": "cQMEu0nbq6cPn2sD",
          "name": "Hellstrider",
          "kind": "passive",
          "description": "A levaloch ignores the effects of non-magical difficult terrain. They take no damage from caltrops or from damaging terrain that deals physical, acid, or cold damage.\nA levaloch can move through liquids up to 5 feet deep at their full Speed.",
          "traits": []
        },
        {
          "id": "dW7bkWhXvNcwfUCh",
          "name": "+1 Status to All Saves vs. Magic",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "u3ndMdQRfiAH7Z7J",
          "name": "Phalanx Fighter",
          "kind": "passive",
          "description": "All devils of equal or lower level adjacent to a levaloch gain a +1 circumstance bonus to their AC as the levaloch shields them from harm.\nEffect: Phalanx Fighter",
          "traits": []
        },
        {
          "id": "rXrJgVzgOwMP7Cbr",
          "name": "Stable Stance",
          "kind": "passive",
          "description": "A levaloch gains a +2 circumstance bonus to their Fortitude DC against being Shoved and to other saving throws to resist being moved against their will.",
          "traits": []
        },
        {
          "id": "T6ZAqc1mMzmpUCtm",
          "name": "Barbed Net",
          "kind": "passive",
          "description": "When a levaloch hits a creature with their barbed net, the net wraps around the target, which becomes Clumsy 1 and takes a –10-foot circumstance penalty to its Speeds. If the Strike was a critical success, the target is also Immobilized.\nWhen a creature Escape DC 22, or if the Strike misses, the net crumbles into rust.\nEach time a creature attempts to Escape, it takes 1d6 slashing damage from the net's barbs, regardless of whether the attempt succeeds.\nEffect: Barbed Net",
          "traits": []
        },
        {
          "id": "X5bjxwBhWpEDkFUA",
          "name": "Forge Weapon",
          "kind": "action",
          "description": "A levaloch reforges part of their barbed iron substance into a new +1 Striking trident or barbed net. Their previous trident crumbles to rust.\nWhen the levaloch is destroyed, any tridents or barbed nets they created crumble to rust.",
          "traits": [
            "manipulate"
          ]
        },
        {
          "id": "sX0MwC23Mvp1YeD2",
          "name": "Merciless Thrust",
          "kind": "passive",
          "description": "When a levaloch hits a creature that has the Clumsy, Enfeebled, Immobilized, or Restrained conditions with a melee trident Strike, the Strike deals an additional 2d6 damage.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
