    "sourceHash": "sha256:ef75bfe2d25f4e0005231f50764bd6f46d1dce20f3ef67906fedd565192c958e",
    "translatableHash": "sha256:bf520fa4c59a09da56787c87b352c7157995355c24e5053b4f3248299f7a1ffc",
    "data": {
      "schemaVersion": 1,
      "name": "Burning Silver Najid",
      "level": 6,
      "rarity": "unique",
      "size": "medium",
      "traits": [
        "humanoid",
        "kitsune"
      ],
      "description": "",
      "armorClass": 24,
      "hitPoints": 91,
      "speedFeet": 30,
      "perception": {
        "modifier": 17,
        "senses": []
      },
      "saves": {
        "fortitude": 11,
        "reflex": 17,
        "will": 14
      },
      "abilities": {
        "str": 3,
        "dex": 5,
        "con": 0,
        "int": 0,
        "wis": 4,
        "cha": 3
      },
      "skills": {
        "acrobatics": 15,
        "athletics": 13,
        "deception": 15,
        "intimidation": 13,
        "society": 13,
        "stealth": 15,
        "thievery": 15
      },
      "languages": [
        "common",
        "hallit",
        "osiriani",
        "tien"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "OsUeCHTp5TWzDLQ1",
          "name": "Dagger",
          "bonus": 15,
          "damage": "1d4+8 piercing",
          "traits": [
            "agile",
            "finesse",
            "versatile-s"
          ]
        },
        {
          "id": "T4GqiGPQptDuDo44",
          "name": "Dagger",
          "bonus": 15,
          "damage": "1d4+8 piercing",
          "traits": [
            "agile",
            "thrown-10",
            "versatile-s"
          ]
        },
        {
          "id": "GW1iChKcTGG6F8ZV",
          "name": "Shortsword",
          "bonus": 15,
          "damage": "2d6+8 piercing",
          "traits": [
            "agile",
            "finesse",
            "magical",
            "versatile-s"
          ]
        }
      ],
      "actions": [
        {
          "id": "4yGrEXXmjvqCtPbL",
          "name": "Burning Strike",
          "kind": "action",
          "description": "Requirements Najid's divine spark is focused in his blades.\nEffect Najid's blades ignite for just a moment. He can make two Strikes with his burning blades, each against the same target and Najid's current multiple attack penalty. If both attacks hit, combine their damage for the purposes of weakness and resistance. Both strikes deal fire damage regardless of the usual damage type. This counts as two attacks when calculating Najid's multiple attack penalty. Najid's focus leaves his blades.",
          "traits": []
        },
        {
          "id": "3mxJAxXK3WS0aU5X",
          "name": "Fennic Scream",
          "kind": "action",
          "description": "Requirements Najid's divine spark is focused in his voice.\nEffect Najid screams at one creature within 20 feet, freezing their muscles with his rage. The target must attempt a check (fortitude, dc:21) save.\nSuccess The target is unaffected.\nFailure The target is Stunned 2.\nFailure the target is Stunned for one round.\nCritical Failure the target is Stunned for one round and Slowed 1 for 1 round thereafter.\nRegardless of outcome, Najid's focus leaves his voice.",
          "traits": []
        },
        {
          "id": "oshU7JjyLUWqtRhZ",
          "name": "Roguish Smile",
          "kind": "action",
          "description": "Requirements Najid's divine spark is focused in his smile.\nEffect Najid focuses on a creature within 30 feet while smiling confidently. The target attempts a check (will, dc:21) save.\nSuccess the target is unaffected.\nFailure the target is Fascinated for one round. The condition ends if Najid uses a hostile action against the target, but not if Najid uses a hostile action against the target's allies.\nCritical Failure the target is fascinated for one minute. The condition ends if Najid uses a hostile action against the target, but not if Najid uses a hostile action against the target's allies.\nRegardless of outcome, Najid's focus leaves his smile.",
          "traits": []
        },
        {
          "id": "Rfe5RFkcdLDaqo3v",
          "name": "Sliver of Divinity",
          "kind": "action",
          "description": "Najid focuses his divine spark into his short swords, his voice, or his smile, allowing himself to use the associated exemplar ability.",
          "traits": [
            "concentrate"
          ]
        }
      ],
      "spellcasting": []
    },
