    "translatableHash": "sha256:54fd3eac591f4337098182d7cf51e37deb931de9d2e81dc62a5372cf38baf194",
    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Earthquake",
      "level": 12,
      "rarity": "uncommon",
      "size": "large",
      "traits": [
        "environmental"
      ],
      "description": "The earth shakes violently side to side, opening a fissure in the ground, partially collapsing builds, and scattering debris in all directions.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 0,
        "details": ""
      },
      "disable": "",
      "isComplex": false,
      "routine": "",
      "reset": "",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "9g9H4sDLhxFuLws6",
          "name": "Quake",
          "kind": "reaction",
          "description": "The ground shakes violently. All creatures in the area take 6d10 bludgeoning damage with a check (reflex, dc:30, basic, options:area-effect) save. On a critical failure, the creature falls into a 40-foot-deep fissure opened by the tremor. They can attempt to Grab an Edge (DC 30 to prevent the fall, with a –2 circumstance penalty due to the moving ground). A creature that falls takes an additional 20 bludgeoning damage falling damage, is knocked Prone, and must be rescued from their predicament by another PC taking one action to pull them free. If any creatures are still in fissures due to previous tremors, they automatically get a Failure on this save.",
          "traits": []
        }
      ]
    },
