    "data": {
      "schemaVersion": 1,
      "name": "The Husk of Deskari",
      "level": 14,
      "rarity": "unique",
      "size": "gargantuan",
      "traits": [
        "aberration",
        "unholy"
      ],
      "description": "",
      "armorClass": 33,
      "hitPoints": 280,
      "speedFeet": 60,
      "perception": {
        "modifier": 22,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 25,
        "reflex": 20,
        "will": 22
      },
      "abilities": {
        "str": 7,
        "dex": 4,
        "con": 7,
        "int": -5,
        "wis": 5,
        "cha": 4
      },
      "skills": {
        "acrobatics": 22,
        "athletics": 25,
        "intimidation": 25
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "acid",
          "death-effects",
          "disease",
          "fear-effects",
          "mental",
          "paralyzed",
          "poison",
          "precision",
          "swarm-mind",
          "unconscious"
        ],
        "resistances": [
          "piercing 8"
        ],
        "weaknesses": [
          "holy 8"
        ]
      },
      "attacks": [
        {
          "id": "lCSVUSnWAwJFDchy",
          "name": "Scythe",
          "bonus": 26,
          "damage": "3d10+7 slashing",
          "traits": [
            "deadly-d10",
            "magical",
            "reach-20",
            "trip"
          ]
        },
        {
          "id": "1IWk32RNY73hRiIT",
          "name": "Bite",
          "bonus": 26,
          "damage": "4d6 acid; 3d8+7 piercing",
          "traits": [
            "reach-10",
            "unarmed"
          ]
        },
        {
          "id": "ikS3GLjyxMa8Iz6K",
          "name": "Stinger",
          "bonus": 26,
          "damage": "3d10+7 piercing; 4d6 acid",
          "traits": [
            "agile",
            "reach-20",
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "XgyTwElt0efdZee1",
          "name": "Locust Horde",
          "kind": "passive",
          "description": "Once the Husk of Deskari has been reduced to 160 hp the surviving locusts retreat inside the Husk rather than surrounding it. At this point the Disgorge Swarm aura ceases to function, the Husk loses its weakness to splash effects and area of effect attacks, and any creature still taking persistent damage from this effect automatically succeeds on their next flat check to remove it.",
          "traits": []
        },
        {
          "id": "94ngVQbPoxdC7Dh2",
          "name": "All-Around Vision",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "QyLMSolqcTIHGUvt",
          "name": "Cacophony",
          "kind": "passive",
          "description": "The droning buzz of locusts fills the air and mingles with the rasping, screeching sounds of the Husk's carapace plates grinding as it moves. Any creature that begins its turn or moves within 60 feet of the Husk of Deskari must attempt a check (fortitude, dc:33) save or be Sickened 1. After attempting the save a creature is immune to the effects of cacophony for 1 minute. On a critical failure, a creature is only immune for 1 round.",
          "traits": [
            "auditory",
            "aura",
            "mental"
          ]
        },
        {
          "id": "83TPiFoH2LMcAVMU",
          "name": "Reactive Strike (Stinger Only)",
          "kind": "reaction",
          "description": "",
          "traits": []
        },
        {
          "id": "vVMdKgyTWynyRuD5",
          "name": "Disgorge Swarm",
          "kind": "action",
          "description": "Millions of fiendish locusts swarm out of the Husk of Deskari, surrounding it in a 30-foot type:emanation. The emanation moves with the Husk and remains until removed by Locust Horde. Any creature that enters or begins its turn in the emanation must attempt a check (reflex, dc:36, options:area-effect,damaging-effect,inflicts:clumsy) save, with effects based on the results of the save.\nCritical Success The creature is unaffected.\nSuccess The creature takes 2d8 piercing damage and is Clumsy 1 for 1 round.\nFailure The creature takes 4d8 piercing damage and is clumsy 1 for 1 minute.\nCritical Failure The creature takes 8d8 piercing damage and is Clumsy 2 for one minute.",
          "traits": []
        },
        {
          "id": "Db3TuNZJTYfa0KY5",
          "name": "Swarmsense",
          "kind": "passive",
          "description": "The Husk of Deskari can see through the eyes of each insect in the swarms infesting its body or those created by its breath weapon. This grants the Husk of Deskari All-Around Vision.",
          "traits": []
        },
        {
          "id": "l5xwHHxOH1GU3dqU",
          "name": "Knockdown",
          "kind": "action",
          "description": "",
          "traits": []
        }
      ],
      "spellcasting": []
    },
