    "data": {
      "schemaVersion": 1,
      "name": "Harbinger of Ingalor (11-12)",
      "level": 9,
      "rarity": "rare",
      "size": "large",
      "traits": [
        "animal",
        "mindless",
        "swarm",
        "unholy"
      ],
      "description": "",
      "armorClass": 25,
      "hitPoints": 107,
      "speedFeet": 5,
      "perception": {
        "modifier": 18,
        "senses": []
      },
      "saves": {
        "fortitude": 17,
        "reflex": 21,
        "will": 12
      },
      "abilities": {
        "str": 0,
        "dex": 6,
        "con": 4,
        "int": -5,
        "wis": 3,
        "cha": -1
      },
      "skills": {
        "acrobatics": 20,
        "survival": 18
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "acid",
          "precision",
          "swarm-mind"
        ],
        "resistances": [
          "bludgeoning 5",
          "piercing 8",
          "slashing 8"
        ],
        "weaknesses": [
          "area-damage 8",
          "holy 5",
          "spirit 5",
          "splash-damage 8"
        ]
      },
      "attacks": [],
      "actions": [
        {
          "id": "thEfvrYAsNuZitrS",
          "name": "Chthonic Cloud",
          "kind": "passive",
          "description": "Creatures inside the swarm's space are Concealed from creatures outside of its space, and vice versa.",
          "traits": []
        },
        {
          "id": "ePP3NZjDxUCuHX26",
          "name": "Disgusting Chorus",
          "kind": "passive",
          "description": "20 feet. The swarm's component members cry out, crawling all over everything and everyone with sickening sounds and limbs. Creatures who enter or begin their turns inside the aura must attempt a check (fortitude, dc:28, options:inflicts:sickened) save. Once a creature has been targeted by this ability, regardless of the result, they are temporarily immune to Disgusting Chorus for 1 hour.\nSuccess No effect.\nFailure The creature becomes Sickened 1, and cannot reduce their sickened condition below 1 while inside the swarm's space.\nCritical Failure The creature becomes Sickened 2, and cannot reduce their sickened condition below 1 while inside the swarm's space.",
          "traits": [
            "auditory",
            "aura"
          ]
        },
        {
          "id": "RUYvF1uM7xGGeJZE",
          "name": "Feast on Flesh",
          "kind": "action",
          "description": "The swarm pulls at flesh just as locusts strip away vegetation. Each enemy in the swarm's space must succeed at a check (fortitude, dc:26, options:area-effect,damaging-effect) save or take 3d6 persistent bleed damage.",
          "traits": []
        },
        {
          "id": "JpDh3EjEwQPgySHs",
          "name": "Swallowed Foulness",
          "kind": "reaction",
          "description": "Trigger A creature begins its turn inside the swarm's space and isn't holding its breath\nEffect Individual insects swarm down the creature's throat and explode, dealing them 1 acid damage and requiring them to make a check (will, dc:28) save.\nSuccess No effect.\nFailure The creature becomes Stupefied 1 until the end of their current turn as they recover from the disgusting experience.\nCritical Failure As success, but until the end of their next turn.",
          "traits": []
        },
        {
          "id": "Yi05a1PP68K9UVev",
          "name": "Thousands of Teeth",
          "kind": "action",
          "description": "Each enemy in the swarm's space takes 3d12 piercing damage (check (reflex, dc:28, basic, options:area-effect) save)",
          "traits": []
        }
      ],
      "spellcasting": []
    },
