    "sourceHash": "sha256:6cf64f67751bf4d553bb1c35ee40ffa5cbe2b96c26c9aeee823c261795027894",
    "translatableHash": "sha256:74b82a6bf1a440642e285ea9b4c84f601ecf25c60f6375a7cd04425438f582dc",
    "data": {
      "schemaVersion": 1,
      "name": "Plaguetooth",
      "level": -1,
      "rarity": "unique",
      "size": "tiny",
      "traits": [
        "fey"
      ],
      "description": "Lone fairies usually need several minutes of elbow grease and a sleeping or restrained subject to extract a tooth.\nTooth fairies spawn when a child's tooth (or, less commonly, an entire child) is buried in terrain rife with fey energies. Hatching from the buried teeth like larvae from an egg, tooth fairies build crude pliers from whatever they can find, then go hunting for more teeth—regardless of the owners' willingness.",
      "armorClass": 15,
      "hitPoints": 8,
      "speedFeet": 10,
      "perception": {
        "modifier": 6,
        "senses": [
          "darkvision"
        ]
      },
      "saves": {
        "fortitude": 2,
        "reflex": 7,
        "will": 4
      },
      "abilities": {
        "str": -2,
        "dex": 3,
        "con": 0,
        "int": -1,
        "wis": 2,
        "cha": 1
      },
      "skills": {
        "acrobatics": 5,
        "stealth": 5,
        "thievery": 6
      },
      "languages": [
        "fey",
        "common"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": [
          "cold-iron 2"
        ]
      },
      "attacks": [
        {
          "id": "PKh7s5uQyxm0yPQg",
          "name": "Pliers",
          "bonus": 7,
          "damage": "1d6 bludgeoning",
          "traits": [
            "disarm",
            "finesse",
            "reach-0"
          ]
        }
      ],
      "actions": [
        {
          "id": "04WUnuVaMwggkQxr",
          "name": "Plaque Burst",
          "kind": "passive",
          "description": "When killed, a tooth fairy bursts into sticky, foul-smelling white dust. Each creature in a 5-foot emanation must succeed at a check (fortitude, dc:16) save or become Sickened 1 (Sickened 2 on a critical failure).",
          "traits": []
        },
        {
          "id": "2kSrspDPmUktGvBB",
          "name": "Tooth Tug",
          "kind": "action",
          "description": "Requirements The tooth fairy's last action was a successful pliers Strike against a creature with teeth\nEffect The tooth fairy attempts a check (thievery, defense:fortitude) check against the creature's Fortitude DC, dealing 2 persistent bleed damage on any result but a critical failure. On a critical success, it also pulls out one of the target's teeth.\nIf the creature loses a tooth, it takes a –1 status penalty to Charisma-based skill checks and must succeed at a check (flat, dc:5) to Cast a Spell unless that spell has the subtle trait. These effects last for 1 day, or until the stolen tooth is returned and the target regains at least 1 Hit Point.\nEffect: Tooth Tug",
          "traits": [
            "manipulate"
          ]
        }
      ],
      "spellcasting": [
        {
          "id": "4ZK6UkKCERwU9jVd",
          "name": "Primal Innate Spells",
          "tradition": "primal",
          "category": "innate",
          "attackModifier": 5,
          "saveDc": 13,
          "spells": [
            {
              "id": "PJd67jQT66Irv4J6",
              "name": "Sleep",
              "rank": 1
            },
            {
              "id": "PiqpWuj18qEfsTgi",
              "name": "Telekinetic Hand",
              "rank": 1
            }
          ]
        }
      ]
    },
