    "sourceHash": "sha256:e4dba376ab287283e0f9eaa61463b32bcaab51643e076c154c14a6ba00fefe3b",
    "translatableHash": "sha256:1909975aad5399a3d86ee079140ae3f7ad18e22b1dca5187318e2af2a7ee9e16",
    "data": {
      "schemaVersion": 1,
      "name": "Gluttonous Geode (Quest 22)",
      "level": 1,
      "rarity": "common",
      "size": "tiny",
      "traits": [
        "earth",
        "elemental"
      ],
      "description": "The vast ranks of earth elementals have been slow to respond to the return of the elemental lords and the Planes of Metal and Wood. These events have not broken the mountains, nor have they blown away the sands.\nEarthy Emotions\nEarth elementals talk even less than most elementals. They're ponderous, weighing decisions so slowly they can crush the energy from a discussion. Their foremost concern is whether a situation can be endured. Though a rare or resplendent treasure might entice an earth elemental, it's difficult to spur any sense of urgency in them without the presence of an immediate threat.",
      "armorClass": 15,
      "hitPoints": 25,
      "speedFeet": 20,
      "perception": {
        "modifier": 6,
        "senses": [
          "darkvision",
          "tremorsense-imprecise-30"
        ]
      },
      "saves": {
        "fortitude": 8,
        "reflex": 4,
        "will": 6
      },
      "abilities": {
        "str": 3,
        "dex": -1,
        "con": 3,
        "int": -4,
        "wis": 1,
        "cha": -3
      },
      "skills": {
        "stealth": 4,
        "survival": 6
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "bleed",
          "paralyzed",
          "poison",
          "sleep"
        ],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "VxqQpzp73MGvDF6J",
          "name": "Crystal Teeth",
          "bonus": 9,
          "damage": "1d4+4 piercing",
          "traits": []
        }
      ],
      "actions": [
        {
          "id": "jxMLm9AzV11AIvo4",
          "name": "Tremorsense (Imprecise) 30 feet",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "iiNeC7jyAcDS6aGh",
          "name": "Attach",
          "kind": "action",
          "description": "The geode Leaps up to 15 feet and makes a crystal teeth Strike. If it hits a creature larger than itself, it can attach to that creature. Doing so is like Grabbing the creature (Escape DC 17), but the geode moves with that creature rather than holding it in place. The geode is Off-Guard while attached. If the geode is killed or pushed away while attached to a creature, that creature takes 1 persistent bleed damage. Escaping the attached geode or removing the geode in other ways doesn't cause bleed damage.",
          "traits": []
        },
        {
          "id": "JQEFb9KA6XUO7dyb",
          "name": "Gnaw",
          "kind": "action",
          "description": "Requirements The geode is attached to a creature\nEffect The geode deals 1d4+2 bludgeoning damage to the creature it's attached to (check (fortitude, dc:17, basic) save).",
          "traits": []
        }
      ],
      "spellcasting": []
    },
