    "data": {
      "schemaVersion": 1,
      "name": "Anxious Baby Scamp Swarm",
      "level": 3,
      "rarity": "uncommon",
      "size": "large",
      "traits": [
        "swarm"
      ],
      "description": "",
      "armorClass": 18,
      "hitPoints": 45,
      "speedFeet": 5,
      "perception": {
        "modifier": 8,
        "senses": [
          "low-light-vision"
        ]
      },
      "saves": {
        "fortitude": 10,
        "reflex": 13,
        "will": 7
      },
      "abilities": {
        "str": 2,
        "dex": 4,
        "con": 3,
        "int": -2,
        "wis": 0,
        "cha": 2
      },
      "skills": {
        "acrobatics": 9,
        "athletics": 7
      },
      "languages": [],
      "defenses": {
        "immunities": [
          "precision",
          "swarm-mind"
        ],
        "resistances": [
          "physical 5"
        ],
        "weaknesses": [
          "area-damage 5",
          "splash-damage 5"
        ]
      },
      "attacks": [],
      "actions": [
        {
          "id": "6HXCsiEmnGjPRFYE",
          "name": "Elemental Draw",
          "kind": "passive",
          "description": "The baby scamp swarm can sense creatures with a connection to the elements. It is drawn to creatures that have cast an elemental spell or used an elemental ability within the last round.",
          "traits": []
        },
        {
          "id": "LMKjcjrOLzAwmZ48",
          "name": "Elemental Conduit",
          "kind": "passive",
          "description": "A creature within the swarm's space that casts an elemental spell or uses an elemental ability does not need to make a flat check. Additionally, the baby scamps empower their spell causing the save DC to be 1 higher.",
          "traits": []
        },
        {
          "id": "m9VusE56Xgs3pe4L",
          "name": "We're Helping!",
          "kind": "action",
          "description": "The Young scamps all try to help the creatures in their space at the same time. Each creature must attempt a check (type:will, dc:17) save.\nCritical Success The creature is affected as if Guidance had been cast on them.\nSuccess The creature is unaffected.\nFailure The creature is Fascinated until the end of their next turn.",
          "traits": []
        },
        {
          "id": "5oNvHeYl8fSWHjol",
          "name": "Wing Buffet",
          "kind": "action",
          "description": "Each creature within the baby scamp swarm's space takes 3d4 bludgeoning damage (check (type:reflex, dc:17, basic:true) save).",
          "traits": []
        }
      ],
      "spellcasting": []
    },
