      "languages": [
        "pyric"
      ],
      "defenses": {
        "immunities": [
          "bleed",
          "paralyzed",
          "poison",
          "sleep",
          "fire"
        ],
        "resistances": [],
        "weaknesses": [
          "cold 3"
        ]
      },
      "attacks": [
        {
          "id": "ceCMdeJVcFk3YwLx",
          "name": "Headbutt",
          "bonus": 11,
          "damage": "1d4 fire; 1d6+2 piercing",
          "traits": [
            "finesse"
          ]
        }
      ],
      "actions": [
        {
          "id": "yAvraJf1ksBAcCOl",
          "name": "Failed Task",
          "kind": "passive",
          "description": "Trigger The animated flame starts its turn outside the village\nEffect The animated flame dissipates.",
          "traits": []
        },
        {
          "id": "UnZj5Xyb8m8zt4Wk",
          "name": "Failing Task",
          "kind": "passive",
          "description": "Trigger The animated flame leaves the village\nEffect The animated flame becomes Stupefied 2.",
          "traits": []
        },
        {
          "id": "JPfXLDy2dYseqUop",
          "name": "Smoke Vision",
          "kind": "passive",
          "description": "The animated flame ignores the Concealed condition from smoke.",
          "traits": []
        },
        {
          "id": "cLrASbjqkG0mqXXT",
          "name": "Fast Healing 2 (While Touching Fire)",
          "kind": "passive",
          "description": "",
          "traits": []
        },
        {
          "id": "gMRZ46sjaLERrmao",
          "name": "Flame Breath",
          "kind": "action",
          "description": "The animated flame breathes flames in a 15-foot cone that deals 2d4+4 fire damage to each creature within the area (check (reflex, dc:19, basic, options:area-effect) save). Creatures that fail the save also take 1d4 persistent fire damage.\nThe animated flame can't use Flame Breath again for 1d4.",
          "traits": [
            "arcane",
            "fire"
          ]
        }
      ],
