    "translatableHash": "sha256:76d9233aa6fc99c27e4016aefe9e82eb338f424f27d2380eff0df847c45ba2a7",
    "data": {
      "schemaVersion": 1,
      "name": "King Pirate Gorilla",
      "level": 3,
      "rarity": "common",
      "size": "large",
      "traits": [
        "animal"
      ],
      "description": "Gorillas can be territorial creatures, particularly if provoked by hunters or the presence of more dangerous monsters. A gorilla uses its fangs and powerful arms to bite and pummel trespassers with wild abandon.\nWhile many apes exhibit peaceful or reclusive behavior, gorillas can be territorial, and the megaprimatus is especially aggressive and dangerous.",
      "armorClass": 18,
      "hitPoints": 45,
      "speedFeet": 30,
      "perception": {
        "modifier": 8,
        "senses": [
          "low-light-vision",
          "scent-imprecise-30"
        ]
      },
      "saves": {
        "fortitude": 12,
        "reflex": 9,
        "will": 6
      },
      "abilities": {
        "str": 4,
        "dex": 2,
        "con": 3,
        "int": -4,
        "wis": 1,
        "cha": -2
      },
      "skills": {
        "acrobatics": 9,
        "athletics": 11,
        "stealth": 7
      },
      "languages": [],
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "attacks": [
        {
          "id": "T50Unm8nAUbNCLxu",
          "name": "Fist",
          "bonus": 11,
          "damage": "2d6+4 bludgeoning",
          "traits": [
            "agile",
            "reach-10",
            "unarmed"
          ]
        },
        {
          "id": "D4XA5YtJ0G4E1and",
          "name": "Jaws",
          "bonus": 11,
          "damage": "1d8+4 piercing",
          "traits": [
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "AZc9w8btLS3tlJmK",
          "name": "Boarding Action",
          "kind": "action",
          "description": "The pirate gorilla swings on a rope or Strides, moving up to double their Speed. If the pirate boarded or disembarked a boat during this movement, they can make a melee Strike at the end of their movement that deals one extra damage die on a hit.",
          "traits": []
        },
        {
          "id": "7PQkG1Vfc7aynb2X",
          "name": "Frightening Display",
          "kind": "action",
          "description": "The gorilla beats its chest in a terrifying display. Creatures within 30-foot emanation must attempt a check (will, dc:20, options:area-effect,inflicts:frightened,inflicts:off-guard) save. While a creature is frightened by this ability, it is Off-Guard to the gorilla.\nCritical Success No effect and temporarily immune for 1 minute.\nSuccess The creature is unaffected.\nFailure The creature is Frightened 1.\nCritical Failure The creature is Frightened 2.",
          "traits": [
            "auditory",
            "emotion",
            "fear",
            "mental"
          ]
        },
        {
          "id": "4PvDXumkGQD2NB4z",
          "name": "Well-Trained",
          "kind": "passive",
          "description": "The pirate gorilla is used to taking orders on board the ship. It loses its immunity to linguistic efects, including appeals to surrender.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
