    "data": {
      "schemaVersion": 1,
      "name": "Naiad Ship Hunter",
      "level": 4,
      "rarity": "uncommon",
      "size": "medium",
      "traits": [
        "amphibious",
        "fey",
        "nymph",
        "water"
      ],
      "description": "Bounty hunters are constantly on the move, whether within city walls or the wilderness, trailing their fugitive quarries for capture... or disposal. Often relying on stealth or deception as much as martial skill, bounty hunters employ a vast array of talents to accomplish their goals and collect the hefty payout.\nWhether they're hired to wage war, protect a caravan, or infiltrate an impenetrable fortress, there's ample work for mercenaries all over Golarion.",
      "armorClass": 21,
      "hitPoints": 60,
      "speedFeet": 25,
      "perception": {
        "modifier": 13,
        "senses": [
          "low-light-vision"
        ]
      },
      "saves": {
        "fortitude": 9,
        "reflex": 12,
        "will": 11
      },
      "abilities": {
        "str": 3,
        "dex": 4,
        "con": 1,
        "int": 0,
        "wis": 3,
        "cha": 0
      },
      "skills": {
        "athletics": 9,
        "deception": 10,
        "diplomacy": 8,
        "intimidation": 8,
        "stealth": 12,
        "survival": 9
      },
      "languages": [
        "common",
        "elven",
        "fey",
        "thalassic"
      ],
      "defenses": {
        "immunities": [],
        "resistances": [
          "fire 3"
        ],
        "weaknesses": [
          "cold-iron 3"
        ]
      },
      "attacks": [
        {
          "id": "0odn31BhTvalgovA",
          "name": "Aqueous Boarding Pike",
          "bonus": 13,
          "damage": "1d10+6 piercing",
          "traits": [
            "magical",
            "reach",
            "shove",
            "water"
          ]
        },
        {
          "id": "NOsEnDWrZNe5mjC0",
          "name": "Water Orb",
          "bonus": 14,
          "damage": "1d8+3 bludgeoning",
          "traits": [
            "magical",
            "water"
          ]
        }
      ],
      "actions": [
        {
          "id": "bolEEyhGC8YjlLhQ",
          "name": "Animal Empathy",
          "kind": "passive",
          "description": "The naiad can ask questions of, receive answers from, and use the Diplomacy skill with animals.",
          "traits": []
        },
        {
          "id": "mCWRIeeB6PFExTmR",
          "name": "Hunt Prey",
          "kind": "action",
          "description": "The naiad ship hunter designates a single creature they can see and hear, or one they're Tracking or Gathering Information about, as their prey. The naiad ship hunter gains a +2 circumstance bonus to Perception checks to Seek the prey, to Survival checks to Track the prey, and to Diplomacy checks to Gather Information about the prey. This effect lasts until they use Hunt Prey again.",
          "traits": [
            "concentrate"
          ]
        },
        {
          "id": "yEaUAKruElpCN6zI",
          "name": "Posse's Edge",
          "kind": "passive",
          "description": "The naiad ship hunter and their allies gain a +1 circumstance bonus on initiative rolls if the opposing side includes their hunted prey.\nEffect: Posse's Edge",
          "traits": []
        },
        {
          "id": "LvkfpNccs65oqyIV",
          "name": "Precision Edge",
          "kind": "passive",
          "description": "The frst time the naiad ship hunter hits their hunted prey in a round, they deal an additional 1d8 precision damage.",
          "traits": []
        }
      ],
      "spellcasting": []
    },
