    "data": {
      "schemaVersion": 1,
      "entryType": "HAZARD",
      "name": "Enraged Sea Life",
      "level": 5,
      "rarity": "unique",
      "size": "large",
      "traits": [
        "environmental"
      ],
      "description": "A swarm of aggressive cuttlefish, octopuses, devil rays, and countless other species of sea life bite and bludgeon Timonithaea's enemies.",
      "armorClass": 0,
      "hitPoints": 0,
      "hardness": 0,
      "stealth": {
        "modifier": 26,
        "details": "(trained)"
      },
      "disable": "check (thievery, dc:23) (trained) to remove the crown from the altar while avoiding being bitten by the swarming sea life; or Dispel Magic (3rd rank; counteract DC 23) to disable the crown's enchantment, breaking Timonithaea's control over the sea creatures.",
      "isComplex": true,
      "routine": "(one action) The sea creatures attack, dealing 1d8+3 bludgeoning damage] damage to each creature hostile to Timonithaea within the temple (check (reflex, dc:22, basic) save).",
      "reset": "",
      "saves": {
        "fortitude": 0,
        "reflex": 0,
        "will": 0
      },
      "defenses": {
        "immunities": [],
        "resistances": [],
        "weaknesses": []
      },
      "actions": [
        {
          "id": "4p7frSBHGFFLs1ae",
          "name": "Aquatic Onslaught",
          "kind": "reaction",
          "description": "Trigger The PCs enter the main temple chamber\nEffect The chamber fills with sea creatures, then rolls initiative.",
          "traits": []
        }
      ]
    },
